import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom'
import { useAuthStore, useAuthHydration } from './store/authStore'
import { Layout } from './components/layout/Layout'
import { ProtectedRoute } from './components/layout/ProtectedRoute'
import { Toaster } from 'react-hot-toast'

// Auth
import LoginPage from './modules/auth/pages/LoginPage'
import ChangePinPage from './modules/auth/pages/ChangePinPage'

// Core Pages
import DashboardPage from './modules/dashboard/pages/DashboardPage'
import CrmPage from './modules/crm/pages/CrmPage'
import SalesPage from './modules/sales/pages/SalesPage'
import SaleDetailPage from './modules/sales/pages/SaleDetailPage'
import InventoryPage from './modules/inventory/pages/InventoryPage'
import ServicePage from './modules/service/pages/ServicePage'
import FollowupDashboardPage from './modules/followup/pages/FollowupDashboardPage'

// Master Data
import CustomersPage from './modules/master/pages/CustomersPage'
import VehiclesPage from './modules/master/pages/VehiclesPage'
import VehicleModelsPage from './modules/master/pages/VehicleModelsPage'
import VendorsPage from './modules/master/pages/VendorsPage'

// Procurement
import ProcurementPage from './modules/procurement/pages/ProcurementPage'
import SparePurchasePage from './modules/procurement/pages/SparePurchasePage'
import TemporaryItemPage from './modules/procurement/pages/TemporaryItemPage'

// Admin

import DealerManagementPage from './modules/admin/pages/DealerManagementPage'
import StaffProfilePage from './modules/staff/pages/StaffProfilePage'
import SetupPage from './modules/setup/pages/SetupPage'

// Print Views
import PrintInvoicePage from './modules/sales/pages/print/PrintInvoicePage'
import PrintChallanPage from './modules/sales/pages/print/PrintChallanPage'
import PrintSchedulePage from './modules/sales/pages/print/PrintSchedulePage'

function App() {
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated)
  const hydrated = useAuthHydration()

  // Wait for auth state to hydrate from localStorage before rendering routes
  if (!hydrated) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-100">
        <div className="text-gray-500">Loading...</div>
      </div>
    )
  }

  return (
    <BrowserRouter>
      <Toaster position="top-right" />
      <Routes>
        {/* Auth Routes */}
        <Route path="/login" element={isAuthenticated ? <Navigate to="/dashboard" replace /> : <LoginPage />} />
        <Route path="/change-pin" element={<ChangePinPage />} />

        {/* Main Application */}
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <Layout />
            </ProtectedRoute>
          }
        >
          <Route index element={<Navigate to="/dashboard" replace />} />
          <Route path="dashboard" element={<DashboardPage />} />

          {/* Core Workflow */}
          <Route path="crm" element={<CrmPage />} />
          <Route path="followups" element={<FollowupDashboardPage />} />
          <Route path="sales" element={<SalesPage />} />
          <Route path="sales/:saleId" element={<SaleDetailPage />} />
          <Route path="inventory" element={<InventoryPage />} />
          <Route path="service" element={<ServicePage />} />

          {/* Procurement */}
          <Route path="procurement" element={
            <ProtectedRoute allowedRoles={['ADMIN', 'DEALER']}>
              <ProcurementPage />
            </ProtectedRoute>
          } />
          <Route path="procurement/spares/new" element={
            <ProtectedRoute allowedRoles={['ADMIN', 'DEALER']}>
              <SparePurchasePage />
            </ProtectedRoute>
          } />
          <Route path="procurement/temporary-items" element={
            <ProtectedRoute allowedRoles={['ADMIN', 'DEALER']}>
              <TemporaryItemPage />
            </ProtectedRoute>
          } />

          {/* Master Data */}
          <Route path="master/customers" element={<CustomersPage />} />
          <Route path="master/vehicles" element={<VehiclesPage />} />
          <Route path="master/models" element={
            <ProtectedRoute allowedRoles={['ADMIN', 'DEALER']}>
              <VehicleModelsPage />
            </ProtectedRoute>
          } />
          <Route path="master/vendors" element={
            <ProtectedRoute allowedRoles={['ADMIN', 'DEALER']}>
              <VendorsPage />
            </ProtectedRoute>
          } />

          {/* Admin & Profile */}
          <Route path="admin/dealers" element={<Navigate to="/admin/staff" replace />} />

          <Route path="staff/profile" element={<StaffProfilePage />} />
          <Route path="setup" element={
            <ProtectedRoute allowedRoles={['ADMIN', 'DEALER']}>
              <SetupPage />
            </ProtectedRoute>
          } />
        </Route>

        {/* Print Views - Outside Layout */}
        <Route path="/print/sale/:saleId/invoice" element={<PrintInvoicePage />} />
        <Route path="/print/sale/:saleId/challan" element={<PrintChallanPage />} />
        <Route path="/print/sale/:saleId/schedule" element={<PrintSchedulePage />} />
      </Routes>
    </BrowserRouter>
  )
}

export default App

import { Link, useLocation } from 'react-router-dom'
import { useAuthStore } from '@/store/authStore'
import {
  LayoutDashboard,
  Users,
  Car,
  ShoppingCart,
  Wrench,
  MessageSquare,
  Package,
  Settings,
  User,
  LogOut,
  ChevronDown,
  CalendarCheck,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { useState } from 'react'

interface MenuItem {
  path: string
  label: string
  icon: any
  roles: string[]
  children?: { path: string; label: string; roles: string[] }[]
}

const menuItems: MenuItem[] = [
  { path: '/dashboard', label: 'Dashboard', icon: LayoutDashboard, roles: ['ADMIN', 'DEALER', 'STAFF'] },
  { path: '/crm', label: 'Leads', icon: MessageSquare, roles: ['ADMIN', 'DEALER', 'STAFF'] },
  { path: '/followups', label: 'Follow-ups', icon: CalendarCheck, roles: ['ADMIN', 'DEALER', 'STAFF'] },
  { path: '/sales', label: 'Sales', icon: ShoppingCart, roles: ['ADMIN', 'DEALER', 'STAFF'] },
  { path: '/service', label: 'Service', icon: Wrench, roles: ['ADMIN', 'DEALER', 'STAFF'] },
  { path: '/procurement', label: 'Purchase', icon: ShoppingCart, roles: ['ADMIN', 'DEALER'] },
  { path: '/inventory', label: 'Inventory', icon: Package, roles: ['ADMIN', 'DEALER', 'STAFF'] },
  {
    path: '/master',
    label: 'Master Data',
    icon: Car,
    roles: ['ADMIN', 'DEALER', 'STAFF'],
    children: [
      { path: '/master/customers', label: 'Customers', roles: ['ADMIN', 'DEALER', 'STAFF'] },
      { path: '/master/vehicles', label: 'Vehicles', roles: ['ADMIN', 'DEALER', 'STAFF'] },
      { path: '/master/models', label: 'Vehicle Models', roles: ['ADMIN', 'DEALER'] },
      { path: '/master/vendors', label: 'Vendors', roles: ['ADMIN', 'DEALER'] },
    ]
  },

  { path: '/setup', label: 'Setup', icon: Settings, roles: ['ADMIN', 'DEALER'] },
]

export function Sidebar() {
  const location = useLocation()
  const { user, hasRole, clearAuth } = useAuthStore()
  const [expandedMenus, setExpandedMenus] = useState<string[]>([])

  const toggleMenu = (path: string) => {
    setExpandedMenus(prev =>
      prev.includes(path) ? prev.filter(p => p !== path) : [...prev, path]
    )
  }

  const filteredItems = menuItems.filter((item) => hasRole(item.roles as any))

  return (
    <div className="w-64 bg-gray-900 text-white min-h-screen flex flex-col">
      <div className="p-6 border-b border-gray-800">
        <h1 className="text-xl font-bold">EV Showroom</h1>
        <p className="text-sm text-gray-400 mt-1">Management System</p>
      </div>

      <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
        {filteredItems.map((item) => {
          const Icon = item.icon
          const isActive = location.pathname === item.path || location.pathname.startsWith(item.path + '/')
          const hasChildren = item.children && item.children.length > 0
          const isExpanded = expandedMenus.includes(item.path)
          const filteredChildren = item.children?.filter(child => hasRole(child.roles as any))

          if (hasChildren) {
            return (
              <div key={item.path}>
                <button
                  onClick={() => toggleMenu(item.path)}
                  className={cn(
                    'w-full flex items-center justify-between gap-3 px-4 py-3 rounded-lg transition-colors',
                    isActive
                      ? 'bg-gray-800 text-white'
                      : 'text-gray-300 hover:bg-gray-800 hover:text-white'
                  )}
                >
                  <div className="flex items-center gap-3">
                    <Icon className="w-5 h-5" />
                    <span>{item.label}</span>
                  </div>
                  <ChevronDown className={cn('w-4 h-4 transition-transform', isExpanded && 'rotate-180')} />
                </button>
                {isExpanded && (
                  <div className="ml-4 mt-1 space-y-1">
                    {filteredChildren?.map(child => (
                      <Link
                        key={child.path}
                        to={child.path}
                        className={cn(
                          'block px-4 py-2 rounded-lg text-sm transition-colors',
                          location.pathname === child.path
                            ? 'bg-primary-600 text-white'
                            : 'text-gray-400 hover:bg-gray-800 hover:text-white'
                        )}
                      >
                        {child.label}
                      </Link>
                    ))}
                  </div>
                )}
              </div>
            )
          }

          return (
            <Link
              key={item.path}
              to={item.path}
              className={cn(
                'flex items-center gap-3 px-4 py-3 rounded-lg transition-colors',
                isActive
                  ? 'bg-primary-600 text-white'
                  : 'text-gray-300 hover:bg-gray-800 hover:text-white'
              )}
            >
              <Icon className="w-5 h-5" />
              <span>{item.label}</span>
            </Link>
          )
        })}
      </nav>

      <div className="p-4 border-t border-gray-800">
        <Link
          to="/staff/profile"
          className="flex items-center gap-3 px-4 py-3 mb-2 rounded-lg text-gray-300 hover:bg-gray-800 hover:text-white transition-colors"
        >
          <User className="w-5 h-5" />
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium truncate">{user?.name || 'User'}</p>
            <p className="text-xs text-gray-400 truncate">{user?.designation || user?.role}</p>
          </div>
        </Link>
        <button
          onClick={clearAuth}
          className="w-full flex items-center gap-3 px-4 py-3 rounded-lg text-gray-300 hover:bg-gray-800 hover:text-white transition-colors"
        >
          <LogOut className="w-5 h-5" />
          <span>Logout</span>
        </button>
      </div>
    </div>
  )
}

import axios, { AxiosError, AxiosInstance } from 'axios'

// Use /api prefix which will be proxied by Vite to http://localhost:8000
// Or set VITE_API_URL=http://localhost:8000 in .env to call backend directly
const API_BASE_URL = import.meta.env.VITE_API_URL || '/api'

// Helper to get token from Zustand's persisted auth-storage
function getAuthToken(): string | null {
  try {
    const authStorage = localStorage.getItem('auth-storage')
    if (authStorage) {
      const parsed = JSON.parse(authStorage)
      return parsed.state?.token || null
    }
  } catch (e) {
    console.error('Error reading auth token:', e)
  }
  return null
}

class ApiClient {
  private client: AxiosInstance

  constructor() {
    this.client = axios.create({
      baseURL: API_BASE_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    })

    // Request interceptor to add auth token
    this.client.interceptors.request.use(
      (config) => {
        const token = getAuthToken()
        if (token) {
          config.headers.Authorization = `Bearer ${token}`
        }
        return config
      },
      (error) => Promise.reject(error)
    )

    // Response interceptor to handle errors
    // NOTE: We do NOT redirect on 401 here - let React Router handle auth state
    this.client.interceptors.response.use(
      (response) => response,
      (error: AxiosError) => {
        // Just reject the error, let the calling code handle it
        // The auth store and ProtectedRoute will handle logout/redirect
        return Promise.reject(error)
      }
    )
  }

  async get<T>(url: string, config?: any): Promise<T> {
    const response = await this.client.get<T>(url, config)
    // If responseType is blob, return the blob data directly
    if (config?.responseType === 'blob') {
      return response.data as T
    }
    return response.data
  }

  async post<T>(url: string, data?: any, config?: any): Promise<T> {
    const response = await this.client.post<T>(url, data, config)
    return response.data
  }

  async put<T>(url: string, data?: any, config?: any): Promise<T> {
    const response = await this.client.put<T>(url, data, config)
    return response.data
  }

  async patch<T>(url: string, data?: any, config?: any): Promise<T> {
    const response = await this.client.patch<T>(url, data, config)
    return response.data
  }

  async delete<T>(url: string, config?: any): Promise<T> {
    const response = await this.client.delete<T>(url, config)
    return response.data
  }
}

export const api = new ApiClient()

// API Response types
export interface ApiError {
  detail: string
}

export interface PaginatedResponse<T> {
  items: T[]
  total: number
  page: number
  pageSize: number
}

import { useState } from 'react'
import { QRCodeSVG } from 'qrcode.react'
import { ShieldCheck, CheckCircle, Copy, AlertTriangle } from 'lucide-react'
import { authApi, TOTPSetupResponse } from '../auth/api/authApi'

export default function SecuritySettings() {
    const [step, setStep] = useState<'start' | 'setup' | 'verify' | 'success'>('start')
    const [totpData, setTotpData] = useState<TOTPSetupResponse | null>(null)
    const [verifyCode, setVerifyCode] = useState('')
    const [error, setError] = useState<string | null>(null)
    const [loading, setLoading] = useState(false)

    const handleStartSetup = async () => {
        setLoading(true)
        setError(null)
        try {
            const data = await authApi.setupTotp()
            setTotpData(data)
            setStep('setup')
        } catch (err: any) {
            setError(err.response?.data?.detail || 'Failed to initialize setup')
        } finally {
            setLoading(false)
        }
    }

    const handleVerify = async () => {
        if (!totpData || verifyCode.length !== 6) return
        setLoading(true)
        setError(null)
        try {
            await authApi.verifyTotp({
                secret: totpData.secret,
                code: verifyCode
            })
            setStep('success')
        } catch (err: any) {
            setError(err.response?.data?.detail || 'Verification failed. Check the code and try again.')
        } finally {
            setLoading(false)
        }
    }

    const copySecret = () => {
        if (totpData?.secret) {
            navigator.clipboard.writeText(totpData.secret)
            alert('Secret copied to clipboard')
        }
    }

    return (
        <div className="max-w-4xl mx-auto p-6">
            <h1 className="text-2xl font-bold text-gray-900 mb-6">Security Settings</h1>

            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
                <div className="flex items-start gap-4 mb-6">
                    <div className="p-3 bg-blue-50 rounded-lg">
                        <ShieldCheck className="w-8 h-8 text-blue-600" />
                    </div>
                    <div>
                        <h2 className="text-lg font-semibold text-gray-900">Two-Factor Authentication (2FA)</h2>
                        <p className="text-gray-500 text-sm mt-1">
                            Secure your account with an authenticator app (Google Authenticator, Authy, etc.).
                            Required for resetting PINs.
                        </p>
                    </div>
                </div>

                {error && (
                    <div className="mb-6 p-4 bg-red-50 text-red-700 rounded-lg flex items-center gap-2">
                        <AlertTriangle className="w-5 h-5" />
                        {error}
                    </div>
                )}

                {step === 'start' && (
                    <div>
                        <p className="text-gray-600 mb-6">
                            2FA adds an extra layer of security to your account. When enabled, you'll need a code from your
                            authenticator app to perform sensitive actions like resetting PINs.
                        </p>
                        <button
                            onClick={handleStartSetup}
                            disabled={loading}
                            className="btn btn-primary"
                        >
                            {loading ? 'Initializing...' : 'Set up 2FA'}
                        </button>
                    </div>
                )}

                {step === 'setup' && totpData && (
                    <div className="space-y-6">
                        <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 flex flex-col items-center">
                            <div className="bg-white p-4 rounded-lg shadow-sm mb-4">
                                <QRCodeSVG value={totpData.provisioning_uri} size={192} />
                            </div>
                            <p className="text-sm font-medium text-gray-900 mb-2">Scan this QR code with your authenticator app</p>
                            <p className="text-xs text-gray-500">Or enter this secret key manually:</p>
                            <div className="flex items-center gap-2 mt-2">
                                <code className="bg-gray-100 px-3 py-1 rounded text-sm font-mono border border-gray-300">
                                    {totpData.secret}
                                </code>
                                <button onClick={copySecret} className="text-gray-500 hover:text-gray-700" title="Copy">
                                    <Copy className="w-4 h-4" />
                                </button>
                            </div>
                        </div>

                        <div className="flex justify-end">
                            <button
                                onClick={() => setStep('verify')}
                                className="btn btn-primary"
                            >
                                Next Step
                            </button>
                        </div>
                    </div>
                )}

                {step === 'verify' && (
                    <div className="max-w-sm mx-auto text-center">
                        <h3 className="text-lg font-medium text-gray-900 mb-2">Verify Setup</h3>
                        <p className="text-sm text-gray-500 mb-6">Enter the 6-digit code from your authenticator app to enable 2FA.</p>

                        <input
                            type="text"
                            value={verifyCode}
                            onChange={(e) => setVerifyCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                            className="input text-center text-2xl tracking-widest font-mono mb-6"
                            placeholder="000000"
                            autoFocus
                        />

                        <div className="flex gap-3 justify-center">
                            <button
                                onClick={() => setStep('setup')}
                                className="btn btn-secondary"
                            >
                                Back
                            </button>
                            <button
                                onClick={handleVerify}
                                disabled={loading || verifyCode.length !== 6}
                                className="btn btn-primary"
                            >
                                {loading ? 'Verifying...' : 'Enable 2FA'}
                            </button>
                        </div>
                    </div>
                )}

                {step === 'success' && (
                    <div className="text-center py-8">
                        <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <CheckCircle className="w-8 h-8 text-green-600" />
                        </div>
                        <h3 className="text-xl font-bold text-gray-900 mb-2">2FA Enabled Successfully!</h3>
                        <p className="text-gray-500 mb-6">
                            Your account is now secured. You can use your authenticator app to generate codes when needed.
                        </p>
                        <button
                            onClick={() => setStep('start')}
                            className="btn btn-secondary"
                        >
                            Done
                        </button>
                    </div>
                )}
            </div>
        </div>
    )
}

import { useState, useEffect } from 'react'
import { toast } from 'react-hot-toast'
import { CheckCircle, Copy, Check, AlertTriangle, X } from 'lucide-react'

interface TempPinModalProps {
    pin: string
    staffName: string
    onClose: () => void
}

export default function TempPinModal({ pin, staffName, onClose }: TempPinModalProps) {
    const [copied, setCopied] = useState(false)

    const copyToClipboard = async () => {
        try {
            if (navigator.clipboard && window.isSecureContext) {
                await navigator.clipboard.writeText(pin)
                setCopied(true)
                toast.success('PIN copied to clipboard')
            } else {
                // Fallback for non-secure contexts
                const textArea = document.createElement("textarea")
                textArea.value = pin
                textArea.style.position = "fixed"
                textArea.style.left = "-9999px"
                textArea.style.top = "0"
                document.body.appendChild(textArea)
                textArea.focus()
                textArea.select()
                try {
                    document.execCommand('copy')
                    setCopied(true)
                    toast.success('PIN copied to clipboard')
                } catch (err) {
                    console.error('Fallback copy failed', err)
                    toast.error('Failed to copy PIN manually')
                }
                document.body.removeChild(textArea)
            }
            setTimeout(() => setCopied(false), 2000)
        } catch (err) {
            console.error('Copy failed', err)
            toast.error('Failed to copy PIN')
        }
    }

    useEffect(() => {
        if (pin) {
            // Auto copy logic with safety check
            const autoCopy = async () => {
                try {
                    if (navigator.clipboard && window.isSecureContext) {
                        await navigator.clipboard.writeText(pin)
                        setCopied(true)
                        toast.success('PIN copied to clipboard automatically')
                        setTimeout(() => setCopied(false), 2000)
                    }
                } catch (err) {
                    // Silently fail auto-copy on non-secure contexts to avoid annoying errors
                    console.warn('Auto-copy not available in this context')
                }
            }
            autoCopy()
        }
    }, [pin])

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[60] p-4">
            <div className="bg-white rounded-lg p-6 max-w-md w-full shadow-xl relative">
                <button
                    onClick={onClose}
                    className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"
                >
                    <X className="w-5 h-5" />
                </button>

                <div className="text-center">
                    <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100 mb-4">
                        <CheckCircle className="h-6 w-6 text-green-600" />
                    </div>

                    <h3 className="text-lg font-medium text-gray-900 mb-2">
                        Staff Created Successfully
                    </h3>

                    <p className="text-sm text-gray-500 mb-4">
                        {staffName} has been created
                    </p>

                    <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-4">
                        <p className="text-sm font-medium text-yellow-800 mb-2">
                            Temporary PIN
                        </p>
                        <div className="flex items-center justify-center gap-2">
                            <code className="text-3xl font-mono font-bold text-yellow-900 tracking-wider">
                                {pin}
                            </code>
                            <button
                                onClick={copyToClipboard}
                                className="ml-2 p-2 hover:bg-yellow-100 rounded transition"
                                title="Copy PIN"
                            >
                                {copied ? (
                                    <Check className="h-5 w-5 text-green-600" />
                                ) : (
                                    <Copy className="h-5 w-5 text-yellow-700" />
                                )}
                            </button>
                        </div>
                    </div>

                    <div className="bg-red-50 border border-red-200 rounded-lg p-3 mb-4">
                        <p className="text-xs text-red-700 flex items-start">
                            <AlertTriangle className="h-4 w-4 mr-2 flex-shrink-0 mt-0.5" />
                            <span>
                                This PIN will only be shown once. Please copy it and share with the user.
                                They must change it on first login.
                            </span>
                        </p>
                    </div>

                    <button
                        onClick={onClose}
                        className="w-full bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition"
                    >
                        I've Copied the PIN
                    </button>
                </div>
            </div>
        </div>
    )
}

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { X, ArrowLeft, ShieldCheck, UserCog, Key } from 'lucide-react'
import { authApi } from '../api/authApi'

interface ForgotPinModalProps {
    onClose: () => void
}

type Mode = 'select' | 'staff-request' | 'totp-reset'

const resetSchema = z.object({
    totp_code: z.string().length(6, 'Code must be 6 digits'),
    new_pin: z.string().length(6, 'PIN must be 6 digits'),
    confirm_pin: z.string().length(6, 'PIN must be 6 digits'),
}).refine((data) => data.new_pin === data.confirm_pin, {
    message: "PINs don't match",
    path: ["confirm_pin"],
})

type ResetForm = z.infer<typeof resetSchema>

export default function ForgotPinModal({ onClose }: ForgotPinModalProps) {
    const [mode, setMode] = useState<Mode>('select')
    const [loading, setLoading] = useState(false)
    const [identifier, setIdentifier] = useState('')
    const [message, setMessage] = useState<{ type: 'success' | 'error' | 'info', text: string } | null>(null)

    const { register, handleSubmit, formState: { errors } } = useForm<ResetForm>({
        resolver: zodResolver(resetSchema)
    })

    // Staff submits a PIN reset request to admin
    const handleStaffRequest = async (e: React.FormEvent) => {
        e.preventDefault()
        if (!identifier.trim()) return

        setLoading(true)
        setMessage(null)
        try {
            const res = await authApi.requestPinReset(identifier)
            setMessage({ type: 'success', text: res.message })
        } catch (err: any) {
            setMessage({ type: 'error', text: err?.response?.data?.detail || 'Failed to submit request' })
        } finally {
            setLoading(false)
        }
    }

    // Admin/Dealer resets own PIN with TOTP
    const onTotpResetSubmit = async (data: ResetForm) => {
        if (!identifier.trim()) {
            setMessage({ type: 'error', text: 'Please enter your mobile number' })
            return
        }
        setLoading(true)
        setMessage(null)
        try {
            const res = await authApi.resetPinSelf({
                mobile: identifier,
                totp_code: data.totp_code,
                new_pin: data.new_pin,
                confirm_pin: data.confirm_pin,
            })
            setMessage({ type: 'success', text: res.message })
            setTimeout(onClose, 2000)
        } catch (err: any) {
            setMessage({ type: 'error', text: err?.response?.data?.detail || 'Reset failed' })
        } finally {
            setLoading(false)
        }
    }

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 relative">
                <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600">
                    <X className="w-5 h-5" />
                </button>

                <h2 className="text-xl font-bold text-gray-900 mb-1">Reset PIN</h2>
                <p className="text-sm text-gray-500 mb-6">Recover access to your account</p>

                {message && (
                    <div className={`mb-6 p-4 rounded-lg text-sm flex items-start
                        ${message.type === 'success' ? 'bg-green-50 text-green-700' :
                            message.type === 'error' ? 'bg-red-50 text-red-700' :
                                'bg-blue-50 text-blue-700'
                        }`}>
                        {message.text}
                    </div>
                )}

                {/* Step 1: Choose reset method */}
                {mode === 'select' && (
                    <div className="space-y-3">
                        <button
                            onClick={() => { setMode('totp-reset'); setMessage(null) }}
                            className="w-full flex items-center gap-4 p-4 border rounded-lg hover:bg-gray-50 transition text-left"
                        >
                            <div className="p-2 bg-blue-100 rounded-lg">
                                <ShieldCheck className="w-6 h-6 text-blue-600" />
                            </div>
                            <div>
                                <h3 className="font-medium text-gray-900">I have Authenticator Access</h3>
                                <p className="text-xs text-gray-500">Reset using your TOTP authenticator app</p>
                            </div>
                        </button>

                        <button
                            onClick={() => { setMode('staff-request'); setMessage(null) }}
                            className="w-full flex items-center gap-4 p-4 border rounded-lg hover:bg-gray-50 transition text-left"
                        >
                            <div className="p-2 bg-orange-100 rounded-lg">
                                <UserCog className="w-6 h-6 text-orange-600" />
                            </div>
                            <div>
                                <h3 className="font-medium text-gray-900">Request Reset from Admin</h3>
                                <p className="text-xs text-gray-500">Staff: Submit reset request for admin approval</p>
                            </div>
                        </button>
                    </div>
                )}

                {/* Staff request flow */}
                {mode === 'staff-request' && (
                    <div>
                        <button
                            onClick={() => { setMode('select'); setMessage(null) }}
                            className="text-sm text-gray-500 flex items-center mb-6 hover:text-gray-900 transition-colors"
                        >
                            <ArrowLeft className="w-4 h-4 mr-1" /> Back
                        </button>

                        <div className="bg-orange-50 p-4 rounded-lg flex items-center gap-3 mb-6">
                            <UserCog className="w-8 h-8 text-orange-600" />
                            <div>
                                <h3 className="font-medium text-gray-900">Request Admin Reset</h3>
                                <p className="text-xs text-gray-500">An admin will generate a temporary PIN for you</p>
                            </div>
                        </div>

                        <form onSubmit={handleStaffRequest} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Mobile Number
                                </label>
                                <input
                                    className="input w-full"
                                    value={identifier}
                                    onChange={(e) => setIdentifier(e.target.value)}
                                    placeholder="Enter your registered mobile number"
                                    required
                                    autoFocus
                                />
                            </div>
                            <button
                                type="submit"
                                disabled={loading || !identifier.trim()}
                                className="btn btn-primary w-full py-2.5"
                            >
                                {loading ? 'Submitting...' : 'Submit Reset Request'}
                            </button>
                        </form>
                    </div>
                )}

                {/* TOTP reset flow (Admin/Dealer) */}
                {mode === 'totp-reset' && (
                    <div>
                        <button
                            onClick={() => { setMode('select'); setMessage(null) }}
                            className="text-sm text-gray-500 flex items-center mb-6 hover:text-gray-900 transition-colors"
                        >
                            <ArrowLeft className="w-4 h-4 mr-1" /> Back
                        </button>

                        <form onSubmit={handleSubmit(onTotpResetSubmit)} className="space-y-5">
                            <div className="bg-gray-50 p-4 rounded-lg flex items-center gap-3 mb-6">
                                <ShieldCheck className="w-8 h-8 text-primary-600" />
                                <div>
                                    <h3 className="font-medium text-gray-900">Authenticator Reset</h3>
                                    <p className="text-xs text-gray-500">Enter your mobile and TOTP code</p>
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Mobile Number</label>
                                <input
                                    className="input w-full"
                                    value={identifier}
                                    onChange={(e) => setIdentifier(e.target.value)}
                                    placeholder="Enter your registered mobile"
                                    required
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Authenticator Code</label>
                                <input
                                    {...register('totp_code')}
                                    className="input w-full font-mono text-center tracking-widest text-lg"
                                    placeholder="000000"
                                    maxLength={6}
                                />
                                {errors.totp_code && <p className="text-red-500 text-xs mt-1">{errors.totp_code.message}</p>}
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">New PIN</label>
                                    <input
                                        type="password"
                                        {...register('new_pin')}
                                        className="input w-full text-center"
                                        placeholder="******"
                                        maxLength={6}
                                    />
                                    {errors.new_pin && <p className="text-red-500 text-xs mt-1">{errors.new_pin.message}</p>}
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Confirm PIN</label>
                                    <input
                                        type="password"
                                        {...register('confirm_pin')}
                                        className="input w-full text-center"
                                        placeholder="******"
                                        maxLength={6}
                                    />
                                    {errors.confirm_pin && <p className="text-red-500 text-xs mt-1">{errors.confirm_pin.message}</p>}
                                </div>
                            </div>

                            <button type="submit" disabled={loading} className="btn btn-primary w-full py-2.5">
                                {loading ? 'Resetting PIN...' : 'Reset PIN'}
                            </button>
                        </form>
                    </div>
                )}
            </div>
        </div>
    )
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { useAuthStore } from '@/store/authStore'
import { authApi } from '../api/authApi'
import { Lock } from 'lucide-react'

const changePinSchema = z.object({
  old_pin: z.string().min(6, 'PIN must be 6 digits').max(6, 'PIN must be 6 digits'),
  new_pin: z.string().min(6, 'PIN must be 6 digits').max(6, 'PIN must be 6 digits'),
  confirm_pin: z.string().min(6, 'PIN must be 6 digits').max(6, 'PIN must be 6 digits'),
}).refine((data) => data.new_pin === data.confirm_pin, {
  message: "PINs don't match",
  path: ['confirm_pin'],
}).refine((data) => data.old_pin !== data.new_pin, {
  message: 'New PIN must be different from old PIN',
  path: ['new_pin'],
})

type ChangePinForm = z.infer<typeof changePinSchema>

export default function ChangePinPage() {
  const navigate = useNavigate()
  const { clearAuth } = useAuthStore()
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<ChangePinForm>({
    resolver: zodResolver(changePinSchema),
  })

  const onSubmit = async (data: ChangePinForm) => {
    setError(null)
    setLoading(true)

    try {
      await authApi.changePin({
        old_pin: data.old_pin,
        new_pin: data.new_pin,
      })
      clearAuth()
      navigate('/login', { state: { message: 'PIN changed successfully. Please login again.' } })
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to change PIN. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-primary-500 to-primary-700 px-4">
      <div className="max-w-md w-full">
        <div className="bg-white rounded-2xl shadow-2xl p-8">
          <div className="text-center mb-8">
            <div className="inline-flex items-center justify-center w-16 h-16 bg-primary-100 rounded-full mb-4">
              <Lock className="w-8 h-8 text-primary-600" />
            </div>
            <h1 className="text-3xl font-bold text-gray-900 mb-2">Change PIN</h1>
            <p className="text-gray-600">You must change your PIN before continuing</p>
          </div>

          <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            {error && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg text-sm">
                {error}
              </div>
            )}

            <div>
              <label htmlFor="old_pin" className="block text-sm font-medium text-gray-700 mb-2">
                Current PIN
              </label>
              <input
                id="old_pin"
                type="password"
                {...register('old_pin')}
                className="input"
                placeholder="Enter current PIN"
                maxLength={6}
              />
              {errors.old_pin && (
                <p className="mt-1 text-sm text-red-600">{errors.old_pin.message}</p>
              )}
            </div>

            <div>
              <label htmlFor="new_pin" className="block text-sm font-medium text-gray-700 mb-2">
                New PIN
              </label>
              <input
                id="new_pin"
                type="password"
                {...register('new_pin')}
                className="input"
                placeholder="Enter new PIN"
                maxLength={6}
              />
              {errors.new_pin && (
                <p className="mt-1 text-sm text-red-600">{errors.new_pin.message}</p>
              )}
            </div>

            <div>
              <label htmlFor="confirm_pin" className="block text-sm font-medium text-gray-700 mb-2">
                Confirm New PIN
              </label>
              <input
                id="confirm_pin"
                type="password"
                {...register('confirm_pin')}
                className="input"
                placeholder="Confirm new PIN"
                maxLength={6}
              />
              {errors.confirm_pin && (
                <p className="mt-1 text-sm text-red-600">{errors.confirm_pin.message}</p>
              )}
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full btn btn-primary py-3 text-lg disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? 'Changing PIN...' : 'Change PIN'}
            </button>
          </form>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { useAuthStore } from '@/store/authStore'
import { useQueryClient } from '@tanstack/react-query'
import { authApi } from '../api/authApi'
import { Car } from 'lucide-react'
import ForgotPinModal from '../components/ForgotPinModal'

const loginSchema = z.object({
  identifier: z.string().min(1, 'Identifier is required'),
  pin: z.string().min(6, 'PIN must be 6 digits').max(6, 'PIN must be 6 digits'),
})

type LoginForm = z.infer<typeof loginSchema>

export default function LoginPage() {
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const { login } = useAuthStore()
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [showForgotPin, setShowForgotPin] = useState(false)
  const [retryTime, setRetryTime] = useState<number | null>(null)

  useEffect(() => {
    let timer: any
    if (retryTime !== null && retryTime > 0) {
      timer = setInterval(() => {
        setRetryTime((prev) => (prev !== null && prev > 0 ? prev - 1 : 0))
      }, 1000)
    } else if (retryTime === 0) {
      setRetryTime(null)
      setError(null)
    }
    return () => clearInterval(timer)
  }, [retryTime])

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60)
    const s = seconds % 60
    return `${m}:${s.toString().padStart(2, '0')}`
  }

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<LoginForm>({
    resolver: zodResolver(loginSchema),
  })

  const onSubmit = async (data: LoginForm) => {
    setError(null)
    setLoading(true)

    try {
      const response = await authApi.login(data)

      // Use the store's login() which properly maps designation → role
      login(response.access_token)

      // Invalidate all cached queries so dashboard fetches fresh data
      await queryClient.invalidateQueries()

      if (response.force_pin_change) {
        navigate('/change-pin')
      } else {
        navigate('/dashboard')
      }
    } catch (err: any) {
      console.error('Login error:', err)

      if (err.response?.status === 423) {
        const detail = err.response.data.detail
        if (typeof detail === 'object' && detail.retry_after) {
          setRetryTime(detail.retry_after)
          setError(`Account locked. Please wait before trying again.`)
          setLoading(false)
          return
        }
      }

      const errorMessage = err.response?.data?.detail || err.message || 'Login failed. Please check your credentials.'
      setError(errorMessage)
    } finally {
      if (!retryTime) setLoading(false)
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-primary-500 to-primary-700 px-4">
      <div className="max-w-md w-full">
        <div className="bg-white rounded-2xl shadow-2xl p-8">
          <div className="text-center mb-8">
            <div className="inline-flex items-center justify-center w-16 h-16 bg-primary-100 rounded-full mb-4">
              <Car className="w-8 h-8 text-primary-600" />
            </div>
            <h1 className="text-3xl font-bold text-gray-900 mb-2">EV Showroom ERP</h1>
            <p className="text-gray-600">Sign in to your account</p>
          </div>

          <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            {error && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg text-sm">
                {error}
              </div>
            )}

            <div>
              <label htmlFor="identifier" className="block text-sm font-medium text-gray-700 mb-2">
                Email or Mobile Number
              </label>
              <input
                id="identifier"
                type="text"
                {...register('identifier')}
                className="input"
                placeholder="Enter email or mobile number"
                autoComplete="username"
              />
              {errors.identifier && (
                <p className="mt-1 text-sm text-red-600">{errors.identifier.message}</p>
              )}
            </div>

            <div>
              <label htmlFor="pin" className="block text-sm font-medium text-gray-700 mb-2">
                PIN
              </label>
              <input
                id="pin"
                type="password"
                {...register('pin')}
                className="input"
                placeholder="Enter 6-digit PIN"
                maxLength={6}
                autoComplete="current-password"
              />
              {errors.pin && (
                <p className="mt-1 text-sm text-red-600">{errors.pin.message}</p>
              )}
            </div>

            <button
              type="submit"
              disabled={loading || retryTime !== null}
              className="w-full btn btn-primary py-3 text-lg disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {retryTime !== null
                ? `Try again in ${formatTime(retryTime)}`
                : loading ? 'Signing in...' : 'Sign In'}
            </button>
          </form>

          <div className="mt-6 flex flex-col items-center gap-4 text-sm text-gray-600">
            <button
              type="button"
              onClick={() => setShowForgotPin(true)}
              className="text-primary-600 hover:text-primary-700 font-medium"
            >
              Forgot PIN?
            </button>
            <p>Use your email or mobile number and PIN to login</p>
          </div>
        </div>
      </div>

      {showForgotPin && (
        <ForgotPinModal onClose={() => setShowForgotPin(false)} />
      )}
    </div>
  )
}

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { billingApi, InvoiceCreate } from '../api/billingApi'
import { Plus, Search, CheckCircle, XCircle } from 'lucide-react'
import { formatDate, formatCurrency } from '@/lib/utils'
import InvoiceForm from '../components/InvoiceForm'
import DeleteConfirmModal from '@/components/ui/DeleteConfirmModal'

export default function BillingPage() {
  const [searchTerm, setSearchTerm] = useState('')
  const [statusFilter, setStatusFilter] = useState<string>('')
  const [showForm, setShowForm] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<any | null>(null)
  const queryClient = useQueryClient()

  // Note: Backend doesn't have a GET endpoint for listing invoices
  // Invoices are managed through sales - they're created per sale
  const invoices: any[] = []
  const isLoading = false

  const createMutation = useMutation({
    mutationFn: (data: InvoiceCreate) => billingApi.createInvoice(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['invoices'] })
      setShowForm(false)
    },
  })

  const deleteMutation = useMutation({
    mutationFn: ({ id, hardDelete }: { id: number; hardDelete?: boolean }) =>
      billingApi.deleteInvoice(id, hardDelete),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['invoices'] })
      setDeleteTarget(null)
    },
  })

  const handleDeleteConfirm = (hardDelete: boolean) => {
    if (deleteTarget) {
      deleteMutation.mutate({ id: deleteTarget.invoice_id, hardDelete })
    }
  }

  const finalizeMutation = useMutation({
    mutationFn: (invoiceId: number) => billingApi.finalizeInvoice(invoiceId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['invoices'] })
    },
  })

  const filteredInvoices = invoices.filter((invoice) => {
    const matchesSearch = invoice.invoice_number.toLowerCase().includes(searchTerm.toLowerCase())
    const matchesStatus = !statusFilter || invoice.invoice_status === statusFilter
    return matchesSearch && matchesStatus
  })

  const handleFinalize = (invoiceId: number) => {
    if (confirm('Finalize this invoice? It cannot be edited after finalization.')) {
      finalizeMutation.mutate(invoiceId)
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Billing</h1>
          <p className="text-gray-600 mt-1">Manage invoices and billing</p>
        </div>
        <button onClick={() => setShowForm(true)} className="btn btn-primary flex items-center gap-2">
          <Plus className="w-5 h-5" />
          New Invoice
        </button>
      </div>

      <div className="flex flex-col sm:flex-row gap-4">
        <div className="flex-1">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search invoices..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="input pl-10"
            />
          </div>
        </div>
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="input sm:w-48"
        >
          <option value="">All Status</option>
          <option value="DRAFT">Draft</option>
          <option value="FINALIZED">Finalized</option>
          <option value="CANCELLED">Cancelled</option>
        </select>
      </div>

      <div className="card">
        {isLoading ? (
          <div className="text-center py-8">
            <p className="text-gray-500">Loading invoices...</p>
          </div>
        ) : filteredInvoices.length === 0 ? (
          <div className="text-center py-8">
            <p className="text-gray-500">No invoices found</p>
          </div>
        ) : (
          <div className="table-container">
            <table className="table">
              <thead>
                <tr>
                  <th>Invoice No</th>
                  <th>Date</th>
                  <th>Type</th>
                  <th>Status</th>
                  <th>Total Amount</th>
                  <th>Created</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredInvoices.map((invoice) => (
                  <tr key={invoice.invoice_id}>
                    <td className="font-medium">{invoice.invoice_number}</td>
                    <td>{formatDate(invoice.invoice_date)}</td>
                    <td>
                      <span className="px-2 py-1 text-xs rounded-full bg-gray-100 text-gray-800">
                        {invoice.invoice_type}
                      </span>
                    </td>
                    <td>
                      <span className={`px-2 py-1 text-xs rounded-full ${invoice.invoice_status === 'FINALIZED'
                        ? 'bg-green-100 text-green-800'
                        : invoice.invoice_status === 'CANCELLED'
                          ? 'bg-red-100 text-red-800'
                          : 'bg-yellow-100 text-yellow-800'
                        }`}>
                        {invoice.invoice_status}
                      </span>
                    </td>
                    <td>{formatCurrency(invoice.total_amount)}</td>
                    <td>{formatDate(invoice.created_at)}</td>
                    <td>
                      {invoice.invoice_status === 'DRAFT' && (
                        <button
                          onClick={() => handleFinalize(invoice.invoice_id)}
                          className="p-2 text-green-600 hover:bg-green-50 rounded"
                          title="Finalize Invoice"
                        >
                          <CheckCircle className="w-4 h-4" />
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showForm && (
        <InvoiceForm
          onSubmit={(data) => createMutation.mutate(data)}
          onClose={() => setShowForm(false)}
          isLoading={createMutation.isPending}
        />
      )}

      <DeleteConfirmModal
        isOpen={!!deleteTarget}
        onClose={() => setDeleteTarget(null)}
        onConfirm={handleDeleteConfirm}
        itemName={deleteTarget ? deleteTarget.invoice_number : ''}
        isPending={deleteMutation.isPending}
      />
    </div>
  )
}

import { api } from '@/lib/api'

export interface Enquiry {
    enquiry_id: number
    lead_id: number
