import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { format, isToday, isPast, isFuture, parseISO } from 'date-fns'
import { Calendar, CheckCircle, Clock, AlertCircle } from 'lucide-react'
import { crmApi, Followup } from '../api/crmApi'
import { cn } from '@/lib/utils'

export default function FollowupDashboard() {
    const queryClient = useQueryClient()
    const [activeTab, setActiveTab] = useState<'today' | 'overdue' | 'upcoming'>('today')
    const [completingId, setCompletingId] = useState<number | null>(null)
    const [remarks, setRemarks] = useState('')
    const [error, setError] = useState<string | null>(null)

    const { data, isLoading } = useQuery({
        queryKey: ['followup-dashboard'],
        queryFn: () => crmApi.getFollowupDashboard('SALES'), // Focus on Sales for now
    })

    const updateMutation = useMutation({
        mutationFn: ({ id, remarks }: { id: number; remarks: string }) =>
            crmApi.updateFollowup(id, { followup_status: 'COMPLETED', remarks }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['followup-dashboard'] })
            setCompletingId(null)
            setRemarks('')
            setError(null)
        },
        onError: (err: any) => {
            setError(err.response?.data?.detail || 'Failed to update follow-up')
        }
    })

    const followups: Followup[] = data?.sales_followups || [] // Assuming data structure returned by API

    const todayFollowups = followups.filter(f => isToday(parseISO(f.scheduled_date)))
    const overdueFollowups = followups.filter(f => isPast(parseISO(f.scheduled_date)) && !isToday(parseISO(f.scheduled_date)))
    const upcomingFollowups = followups.filter(f => isFuture(parseISO(f.scheduled_date)))

    const currentList = activeTab === 'today' ? todayFollowups
        : activeTab === 'overdue' ? overdueFollowups
            : upcomingFollowups

    const handleComplete = (id: number) => {
        if (!remarks.trim()) {
            setError('Remarks are required to complete a follow-up')
            return
        }
        updateMutation.mutate({ id, remarks })
    }

    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden h-full flex flex-col">
            <div className="p-4 border-b border-gray-200 flex justify-between items-center">
                <h3 className="font-semibold text-gray-900 flex items-center gap-2">
                    <Calendar className="w-5 h-5 text-gray-500" />
                    Pending Follow-ups
                </h3>
                <div className="flex gap-1 text-sm bg-gray-100 p-1 rounded-lg">
                    <button
                        onClick={() => setActiveTab('overdue')}
                        className={cn(
                            "px-3 py-1 rounded-md transition-colors",
                            activeTab === 'overdue' ? "bg-white shadow text-red-600 font-medium" : "text-gray-500 hover:text-gray-700"
                        )}
                    >
                        Overdue ({overdueFollowups.length})
                    </button>
                    <button
                        onClick={() => setActiveTab('today')}
                        className={cn(
                            "px-3 py-1 rounded-md transition-colors",
                            activeTab === 'today' ? "bg-white shadow text-blue-600 font-medium" : "text-gray-500 hover:text-gray-700"
                        )}
                    >
                        Today ({todayFollowups.length})
                    </button>
                    <button
                        onClick={() => setActiveTab('upcoming')}
                        className={cn(
                            "px-3 py-1 rounded-md transition-colors",
                            activeTab === 'upcoming' ? "bg-white shadow text-green-600 font-medium" : "text-gray-500 hover:text-gray-700"
                        )}
                    >
                        Upcoming ({upcomingFollowups.length})
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-3">
                {isLoading ? (
                    <p className="text-center text-gray-500 py-4">Loading...</p>
                ) : currentList.length === 0 ? (
                    <p className="text-center text-gray-500 py-8">No {activeTab} follow-ups</p>
                ) : (
                    currentList.map(f => (
                        <div key={f.followup_id} className="border border-gray-100 rounded-lg p-3 hover:bg-gray-50 transition-colors">
                            <div className="flex justify-between items-start">
                                <div>
                                    <p className="font-medium text-gray-900">Lead #{f.lead_id}</p>
                                    <p className="text-sm text-gray-500 flex items-center gap-1 mt-1">
                                        <Clock className="w-3 h-3" />
                                        {format(parseISO(f.scheduled_date), 'PPP')}
                                    </p>
                                    {f.remarks && (
                                        <p className="text-xs text-gray-400 mt-2 italic">"{f.remarks}"</p>
                                    )}
                                </div>
                                {completingId === f.followup_id ? (
                                    <div className="bg-white border border-gray-200 rounded p-2 shadow-sm w-64 z-10">
                                        <p className="text-xs font-semibold mb-2">Add Result/Remarks</p>
                                        <textarea
                                            value={remarks}
                                            onChange={(e) => setRemarks(e.target.value)}
                                            className="w-full text-sm border-gray-300 rounded mb-2 h-20 p-2"
                                            placeholder="What happened? Set next steps..."
                                        />
                                        {error && <p className="text-xs text-red-500 mb-2">{error}</p>}
                                        <div className="flex justify-end gap-2">
                                            <button
                                                onClick={() => { setCompletingId(null); setRemarks(''); setError(null); }}
                                                className="text-xs text-gray-500 hover:text-gray-700"
                                            >
                                                Cancel
                                            </button>
                                            <button
                                                onClick={() => handleComplete(f.followup_id)}
                                                disabled={updateMutation.isPending}
                                                className="px-2 py-1 bg-blue-600 text-white text-xs rounded hover:bg-blue-700"
                                            >
                                                {updateMutation.isPending ? 'Saving...' : 'Complete'}
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <button
                                        onClick={() => setCompletingId(f.followup_id)}
                                        className="text-gray-400 hover:text-green-600 transition-colors"
                                        title="Mark as Complete"
                                    >
                                        <CheckCircle className="w-5 h-5" />
                                    </button>
                                )}
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    )
}

import { useState } from 'react'
import { X, Calendar, Plus, MessageSquare, Car, FileCheck } from 'lucide-react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { leadsApi } from '../api/leads'
import { api } from '@/lib/api'
import toast from 'react-hot-toast'
import LeadConversionModal from './LeadConversionModal'
import { formatDate } from '@/lib/utils'

interface LeadDetailsModalProps {
    leadId: number
    onClose: () => void
}

export default function LeadDetailsModal({ leadId, onClose }: LeadDetailsModalProps) {
    const [activeTab, setActiveTab] = useState<'details' | 'followups' | 'testrides'>('details')
    const [showConversionModal, setShowConversionModal] = useState(false)
    const queryClient = useQueryClient()

    const { data: lead, isLoading: leadLoading } = useQuery({
        queryKey: ['lead', leadId],
        queryFn: () => leadsApi.getById(leadId),
    })

    // Follow-ups state
    const [remarks, setRemarks] = useState('')
    const [outcomeStatus, setOutcomeStatus] = useState('WARM')
    const [nextDate, setNextDate] = useState('')

    const { data: followups = [], isLoading: followupsLoading } = useQuery({
        queryKey: ['lead-followups', leadId],
        queryFn: () => api.get(`/crm/leads/${leadId}/followups`).then((res: any) => res.data),
    })

    const addFollowupMutation = useMutation({
        mutationFn: (data: any) => leadsApi.addLeadFollowup(leadId, data),
        onSuccess: () => {
            toast.success('Follow-up recorded')
            queryClient.invalidateQueries({ queryKey: ['lead-followups', leadId] })
            setRemarks('')
        },
        onError: (err: any) => {
            toast.error(err?.response?.data?.detail || 'Failed to add follow-up')
        }
    })

    // Test Rides state
    const [chassisNo, setChassisNo] = useState('')
    const [rideDate, setRideDate] = useState(new Date().toISOString().split('T')[0])
    const [feedback, setFeedback] = useState('')

    const { data: testRides = [], isLoading: testRidesLoading } = useQuery({
        queryKey: ['test-rides', leadId],
        queryFn: () => leadsApi.getTestRides(leadId),
    })

    // Fetch available vehicles for the model
    const { data: vehicles = [] } = useQuery({
        queryKey: ['vehicles', lead?.vehicle_model_id],
        queryFn: () => api.get(`/master/vehicles`, { params: { vehicle_model_id: lead?.vehicle_model_id, status: 'IN_STOCK,DEMO' } }).then((res: any) => res.data),
        enabled: !!lead?.vehicle_model_id && activeTab === 'testrides',
    })

    const addTestRideMutation = useMutation({
        mutationFn: (data: any) => leadsApi.addTestRide(leadId, data),
        onSuccess: () => {
            toast.success('Test ride recorded')
            queryClient.invalidateQueries({ queryKey: ['test-rides', leadId] })
            setChassisNo('')
            setFeedback('')
        },
        onError: (err: any) => {
            toast.error(err?.response?.data?.detail || 'Failed to add test ride')
        }
    })

    if (leadLoading) {
        return (
            <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
                <div className="bg-white rounded-lg p-6">Loading lead details...</div>
            </div>
        )
    }

    if (!lead) return null;

    if (showConversionModal) {
        return (
            <LeadConversionModal
                lead={lead as any}
                onClose={() => setShowConversionModal(false)}
                onSuccess={() => {
                    setShowConversionModal(false)
                    onClose()
                }}
            />
        )
    }

    const isConvertible = lead.lead_status !== 'SOLD' && lead.lead_status !== 'LOST'

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-40">
            <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] flex flex-col overflow-hidden">
                {/* Header */}
                <div className="bg-gray-50 border-b border-gray-200 px-6 py-4 flex items-center justify-between">
                    <div>
                        <h2 className="text-xl font-semibold flex items-center gap-2">
                            {lead.name}
                            <span className={`px-2.5 py-0.5 rounded-full text-xs font-semibold
                                ${lead.lead_status === 'HOT' ? 'bg-red-100 text-red-800' :
                                    lead.lead_status === 'WARM' ? 'bg-yellow-100 text-yellow-800' :
                                        lead.lead_status === 'COLD' ? 'bg-blue-100 text-blue-800' :
                                            lead.lead_status === 'SOLD' ? 'bg-green-100 text-green-800' :
                                                'bg-gray-100 text-gray-800'
                                }`}>
                                {lead.lead_status || 'Unknown'}
                            </span>
                        </h2>
                        <p className="text-sm text-gray-500 mt-1">{lead.phone} | {lead.lead_source}</p>
                    </div>
                    <div className="flex items-center gap-3">
                        {isConvertible && (
                            <button
                                onClick={() => setShowConversionModal(true)}
                                className="btn btn-primary flex items-center gap-2"
                            >
                                <FileCheck className="w-4 h-4" />
                                Convert to Customer
                            </button>
                        )}
                        <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded">
                            <X className="w-5 h-5" />
                        </button>
                    </div>
                </div>

                {/* Tabs */}
                <div className="flex border-b border-gray-200">
                    <button onClick={() => setActiveTab('details')} className={`px-6 py-3 font-medium text-sm transition-colors border-b-2 ${activeTab === 'details' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>Details</button>
                    <button onClick={() => setActiveTab('followups')} className={`px-6 py-3 font-medium text-sm transition-colors border-b-2 ${activeTab === 'followups' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>Follow-ups</button>
                    <button onClick={() => setActiveTab('testrides')} className={`px-6 py-3 font-medium text-sm transition-colors border-b-2 ${activeTab === 'testrides' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>Test Rides</button>
                </div>

                {/* Content */}
                <div className="p-6 overflow-y-auto flex-1 bg-gray-50">
                    {activeTab === 'details' && (
                        <div className="space-y-6">
                            <div className="grid grid-cols-2 gap-4 bg-white p-4 rounded-lg shadow-sm">
                                <div>
                                    <p className="text-sm text-gray-500">Contact</p>
                                    <p className="font-medium">{lead.phone}</p>
                                    <p className="text-sm">{lead.email || 'No email'}</p>
                                </div>
                                <div>
                                    <p className="text-sm text-gray-500">Interested Model</p>
                                    <p className="font-medium">Model ID: {lead.vehicle_model_id}</p>
                                </div>
                                <div>
                                    <p className="text-sm text-gray-500">Owner Staff ID</p>
                                    <p className="font-medium">{lead.owner_staff_id}</p>
                                </div>
                                <div>
                                    <p className="text-sm text-gray-500">Expected Purchase</p>
                                    <p className="font-medium">{lead.expected_purchase_date ? formatDate(lead.expected_purchase_date) : 'N/A'}</p>
                                </div>
                            </div>
                            {lead.remarks && (
                                <div className="bg-white p-4 rounded-lg shadow-sm">
                                    <p className="text-sm text-gray-500 mb-1">Remarks</p>
                                    <p className="text-sm">{lead.remarks}</p>
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'followups' && (
                        <div className="space-y-6">
                            <div className="bg-white p-4 rounded-lg shadow-sm space-y-3">
                                <h3 className="font-medium text-gray-800">Log New Follow-up</h3>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs text-gray-500 mb-1">Outcome</label>
                                        <select value={outcomeStatus} onChange={e => setOutcomeStatus(e.target.value)} className="input text-sm">
                                            <option value="HOT">HOT</option>
                                            <option value="WARM">WARM</option>
                                            <option value="COLD">COLD</option>
                                            <option value="LOST">LOST</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="block text-xs text-gray-500 mb-1">Next Follow-up Date</label>
                                        <input type="date" value={nextDate} onChange={e => setNextDate(e.target.value)} className="input text-sm" />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs text-gray-500 mb-1">Remarks (Min 10 chars) *</label>
                                    <textarea value={remarks} onChange={e => setRemarks(e.target.value)} className="input text-sm" rows={2} placeholder="Summary of discussion..."></textarea>
                                </div>
                                <button
                                    onClick={() => addFollowupMutation.mutate({ remarks, outcome_status: outcomeStatus, next_followup_date: nextDate || undefined })}
                                    disabled={remarks.length < 10 || addFollowupMutation.isPending}
                                    className="btn btn-primary text-sm w-full"
                                >
                                    {addFollowupMutation.isPending ? 'Saving...' : 'Save Follow-up'}
                                </button>
                            </div>

                            <div className="space-y-3">
                                <h3 className="font-medium text-gray-700">Past Follow-ups</h3>
                                {followupsLoading ? <p className="text-sm text-gray-500">Loading...</p> : followups.length === 0 ? <p className="text-sm text-gray-500">No follow-ups recorded.</p> : followups.map((f: any) => (
                                    <div key={f.lead_followup_id} className="bg-white p-3 rounded-lg shadow-sm text-sm border-l-4 border-blue-500">
                                        <div className="flex justify-between items-start mb-1">
                                            <span className="font-medium text-blue-800">{f.outcome_status}</span>
                                            <span className="text-gray-400 text-xs">{formatDate(f.followup_date)}</span>
                                        </div>
                                        <p className="text-gray-700">{f.remarks}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {activeTab === 'testrides' && (
                        <div className="space-y-6">
                            <div className="bg-white p-4 rounded-lg shadow-sm space-y-3">
                                <h3 className="font-medium text-gray-800">Record Test Ride</h3>
                                <div>
                                    <label className="block text-xs text-gray-500 mb-1">Select Physical Vehicle (Chassis) *</label>
                                    <select value={chassisNo} onChange={e => setChassisNo(e.target.value)} className="input text-sm">
                                        <option value="">-- Choose a vehicle --</option>
                                        {(vehicles?.data || vehicles).map((v: any) => (
                                            <option key={v.chassis_no} value={v.chassis_no}>
                                                {v.chassis_no} ({v.current_status})
                                            </option>
                                        ))}
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs text-gray-500 mb-1">Date *</label>
                                    <input type="date" value={rideDate} onChange={e => setRideDate(e.target.value)} className="input text-sm" />
                                </div>
                                <div>
                                    <label className="block text-xs text-gray-500 mb-1">Customer Feedback</label>
                                    <textarea value={feedback} onChange={e => setFeedback(e.target.value)} className="input text-sm" rows={2} placeholder="How was the ride?"></textarea>
                                </div>
                                <button
                                    onClick={() => addTestRideMutation.mutate({ chassis_no: chassisNo, test_ride_date: rideDate, customer_feedback: feedback })}
                                    disabled={!chassisNo || !rideDate || addTestRideMutation.isPending}
                                    className="btn btn-primary text-sm w-full"
                                >
                                    {addTestRideMutation.isPending ? 'Saving...' : 'Record Test Ride'}
                                </button>
                            </div>

                            <div className="space-y-3">
                                <h3 className="font-medium text-gray-700">Past Test Rides</h3>
                                {testRidesLoading ? <p className="text-sm text-gray-500">Loading...</p> : testRides.length === 0 ? <p className="text-sm text-gray-500">No test rides recorded.</p> : testRides.map((tr: any) => (
                                    <div key={tr.test_ride_id} className="bg-white p-3 rounded-lg shadow-sm text-sm border-l-4 border-green-500">
                                        <div className="flex justify-between items-start mb-1">
                                            <span className="font-medium text-green-800">Chassis: {tr.chassis_no}</span>
                                            <span className="text-gray-400 text-xs">{formatDate(tr.test_ride_date)}</span>
                                        </div>
                                        {tr.customer_feedback && <p className="text-gray-700 italic">"{tr.customer_feedback}"</p>}
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    )
}

import { useState } from 'react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import { X } from 'lucide-react'
import { leadsApi } from '../api/leads'
import { useMasterStore } from '@/store/masterStore'

interface LeadFollowupModalProps {
    leadId: number
    leadName: string
    onClose: () => void
}

export default function LeadFollowupModal({ leadId, leadName, onClose }: LeadFollowupModalProps) {
    const queryClient = useQueryClient()
    const { leadStatuses } = useMasterStore()

    const [remarks, setRemarks] = useState('')
    const [outcomeStatus, setOutcomeStatus] = useState('')
    const [nextFollowupDate, setNextFollowupDate] = useState('')
    const [error, setError] = useState<string | null>(null)

    const mutation = useMutation({
        mutationFn: (data: { remarks: string; outcome_status: string; next_followup_date?: string }) =>
            leadsApi.addLeadFollowup(leadId, data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['leads'] })
            queryClient.invalidateQueries({ queryKey: ['followup-dashboard'] })
            onClose()
        },
        onError: (err: any) => {
            setError(err?.response?.data?.detail || 'Failed to log follow-up.')
        },
    })

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault()
        setError(null)

        if (!remarks.trim()) {
            setError('A remark is strictly mandatory for logging a follow-up.')
            return
        }
        if (remarks.trim().length < 10) {
            setError('Remarks must be at least 10 characters.')
            return
        }
        if (!outcomeStatus) {
            setError('Please select an outcome status.')
            return
        }

        mutation.mutate({
            remarks: remarks.trim(),
            outcome_status: outcomeStatus,
            next_followup_date: nextFollowupDate || undefined,
        })
    }

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-lg max-w-md w-full">
                <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between">
                    <div>
                        <h2 className="text-xl font-semibold">Log Follow-Up</h2>
                        <p className="text-sm text-gray-500 mt-0.5">{leadName}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    {/* Remark — Mandatory */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            Remark <span className="text-red-500">*</span>
                        </label>
                        <textarea
                            required
                            value={remarks}
                            onChange={(e) => setRemarks(e.target.value)}
                            className="input w-full"
                            rows={3}
                            placeholder="What happened? Minimum 10 characters..."
                            minLength={10}
                        />
                    </div>

                    {/* Outcome Status — Dynamic from lead_status_master */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            Outcome Status <span className="text-red-500">*</span>
                        </label>
                        <select
                            required
                            value={outcomeStatus}
                            onChange={(e) => setOutcomeStatus(e.target.value)}
                            className="input w-full"
                        >
                            <option value="">Select outcome</option>
                            {leadStatuses.map((status: any) => (
                                <option key={status.status_id} value={status.status_name}>
                                    {status.status_name}
                                </option>
                            ))}
                        </select>
                    </div>

                    {/* Next Follow-up Date — Optional */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            Next Follow-up Date
                        </label>
                        <input
                            type="date"
                            value={nextFollowupDate}
                            onChange={(e) => setNextFollowupDate(e.target.value)}
                            className="input w-full"
                            min={new Date().toISOString().split('T')[0]}
                        />
                        <p className="text-xs text-gray-400 mt-1">
                            Optional — schedule when to follow up next
                        </p>
                    </div>

                    {/* Error */}
                    {error && (
                        <div className="p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700">
                            {error}
                        </div>
                    )}

                    {/* Actions */}
                    <div className="flex justify-end gap-3 pt-4 border-t">
                        <button type="button" onClick={onClose} className="btn btn-secondary">
                            Cancel
                        </button>
                        <button type="submit" disabled={mutation.isPending} className="btn btn-primary">
                            {mutation.isPending ? 'Saving...' : 'Log Follow-Up'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    )
}

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { leadsApi } from '../api/leads'
import { api } from '@/lib/api'
import { formatDate } from '@/lib/utils'
import { Calendar, Plus, Bike, MessageCircle } from 'lucide-react'
import toast from 'react-hot-toast'

interface TestRide {
    test_ride_id: number
    lead_id: number
    vehicle_model_id: number
    test_ride_date: string
    customer_feedback?: string
    created_at: string
}

export default function TestRideList() {
    const queryClient = useQueryClient()
    const [selectedLeadId, setSelectedLeadId] = useState<number | null>(null)
    const [showForm, setShowForm] = useState(false)
    const [formData, setFormData] = useState({
        chassis_no: '',
        test_ride_date: new Date().toISOString().split('T')[0],
        customer_feedback: '',
        lead_id: '',
    })

    const { data: leads = [] } = useQuery<any[]>({
        queryKey: ['leads'],
        queryFn: () => api.get<any[]>('/crm/leads'),
    })

    const selectedLeadObj = leads.find((l: any) => l.lead_id === parseInt(formData.lead_id))

    const { data: vehicles = [] } = useQuery<any[]>({
        queryKey: ['vehicles', selectedLeadObj?.vehicle_model_id],
        queryFn: () => api.get<any[]>('/master/vehicles', { params: { vehicle_model_id: selectedLeadObj?.vehicle_model_id, status: 'IN_STOCK,DEMO' } }),
        enabled: !!selectedLeadObj?.vehicle_model_id,
    })

    const { data: testRides = [], isLoading } = useQuery<TestRide[]>({
        queryKey: ['test-rides', selectedLeadId],
        queryFn: () => leadsApi.getTestRides(selectedLeadId!),
        enabled: !!selectedLeadId,
    })

    const addTestRideMutation = useMutation({
        mutationFn: () => {
            const leadId = parseInt(formData.lead_id)
            return leadsApi.addTestRide(leadId, {
                chassis_no: formData.chassis_no,
                test_ride_date: formData.test_ride_date,
                customer_feedback: formData.customer_feedback || undefined,
            })
        },
        onSuccess: () => {
            toast.success('Test ride recorded')
            queryClient.invalidateQueries({ queryKey: ['test-rides'] })
            setShowForm(false)
            setFormData({
                chassis_no: '',
                test_ride_date: new Date().toISOString().split('T')[0],
                customer_feedback: '',
                lead_id: '',
            })
        },
        onError: (err: any) => {
            toast.error(err?.response?.data?.detail || 'Failed to record test ride')
        },
    })

    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <label className="text-sm font-medium text-gray-600">Filter by Lead:</label>
                    <select
                        value={selectedLeadId ?? ''}
                        onChange={(e) => setSelectedLeadId(e.target.value ? parseInt(e.target.value) : null)}
                        className="input max-w-xs"
                    >
                        <option value="">Select a lead</option>
                        {leads.map((lead: any) => (
                            <option key={lead.lead_id} value={lead.lead_id}>
                                {lead.name} — {lead.phone}
                            </option>
                        ))}
                    </select>
                </div>
                <button onClick={() => setShowForm(true)} className="btn btn-primary flex items-center gap-2">
                    <Plus className="w-4 h-4" />
                    Record Test Ride
                </button>
            </div>

            {/* Test Ride Form Modal */}
            {showForm && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
                    <div className="bg-white rounded-lg max-w-md w-full p-6">
                        <h3 className="text-lg font-semibold mb-4">Record Test Ride</h3>
                        <div className="space-y-3">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Lead *</label>
                                <select
                                    value={formData.lead_id}
                                    onChange={(e) => setFormData({ ...formData, lead_id: e.target.value, chassis_no: '' })}
                                    className="input"
                                >
                                    <option value="">Select lead</option>
                                    {leads.map((lead: any) => (
                                        <option key={lead.lead_id} value={lead.lead_id}>
                                            {lead.name} — {lead.phone}
                                        </option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Physical Vehicle *</label>
                                <select
                                    value={formData.chassis_no}
                                    onChange={(e) => setFormData({ ...formData, chassis_no: e.target.value })}
                                    className="input"
                                    disabled={!formData.lead_id}
                                >
                                    <option value="">Select vehicle</option>
                                    {(vehicles?.data || vehicles).map((v: any) => (
                                        <option key={v.chassis_no} value={v.chassis_no}>
                                            {v.chassis_no} ({v.current_status})
                                        </option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Date *</label>
                                <input
                                    type="date"
                                    value={formData.test_ride_date}
                                    onChange={(e) => setFormData({ ...formData, test_ride_date: e.target.value })}
                                    className="input"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Customer Feedback</label>
                                <textarea
                                    value={formData.customer_feedback}
                                    onChange={(e) => setFormData({ ...formData, customer_feedback: e.target.value })}
                                    className="input"
                                    rows={3}
                                    placeholder="How was the experience?"
                                />
                            </div>
                        </div>
                        <div className="flex justify-end gap-3 mt-4">
                            <button onClick={() => setShowForm(false)} className="btn btn-secondary">Cancel</button>
                            <button
                                onClick={() => addTestRideMutation.mutate()}
                                disabled={!formData.lead_id || !formData.vehicle_model_id || addTestRideMutation.isPending}
                                className="btn btn-primary"
                            >
                                {addTestRideMutation.isPending ? 'Saving...' : 'Save'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Test Rides List */}
            {!selectedLeadId ? (
                <div className="text-center py-12 text-gray-400">
                    <Bike className="w-12 h-12 mx-auto mb-3 opacity-50" />
                    <p>Select a lead to view test rides</p>
                </div>
            ) : isLoading ? (
                <div className="text-center py-8 text-gray-500">Loading test rides...</div>
            ) : testRides.length === 0 ? (
                <div className="text-center py-12 text-gray-400">
                    <Bike className="w-12 h-12 mx-auto mb-3 opacity-50" />
                    <p>No test rides recorded for this lead</p>
                </div>
            ) : (
                <div className="space-y-3">
                    {testRides.map((ride) => (
                        <div key={ride.test_ride_id} className="border border-gray-200 rounded-lg p-4 hover:bg-gray-50">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 bg-blue-100 rounded-lg">
                                        <Bike className="w-4 h-4 text-blue-600" />
                                    </div>
                                    <div>
                                        <p className="font-medium text-gray-900">Model #{ride.vehicle_model_id}</p>
                                        <p className="text-xs text-gray-500 flex items-center gap-1">
                                            <Calendar className="w-3 h-3" />
                                            {formatDate(ride.test_ride_date)}
                                        </p>
                                    </div>
                                </div>
                            </div>
                            {ride.customer_feedback && (
                                <div className="mt-2 flex items-start gap-2 bg-gray-50 p-2 rounded">
                                    <MessageCircle className="w-4 h-4 text-gray-400 mt-0.5" />
                                    <p className="text-sm text-gray-600 italic">"{ride.customer_feedback}"</p>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            )}
        </div>
    )
}

import { useEffect, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useMutation } from '@tanstack/react-query'
import { leadsApi, LeadCreate } from '../api/leads'
import { Plus, Search, Eye, UserPlus, Trash2, ClipboardList } from 'lucide-react'
import { formatDate } from '@/lib/utils'
import LeadForm from '../components/LeadForm'
import LeadConversionModal from '../components/LeadConversionModal'
import LeadFollowupModal from '../components/LeadFollowupModal'
import LeadDetailsModal from '../components/LeadDetailsModal'
import TestRideList from '../components/TestRideList'
import { useCrmStore } from '@/store/crmStore'
import { useMasterStore } from '@/store/masterStore'
import DeleteConfirmModal from '@/components/ui/DeleteConfirmModal'

export default function CrmPage() {
  const [searchTerm, setSearchTerm] = useState('')
  const [statusFilter, setStatusFilter] = useState<number | ''>('')
  const [showForm, setShowForm] = useState(false)
  const [convertingLead, setConvertingLead] = useState<any>(null)
  const [selectedLead, setSelectedLead] = useState<any>(null)
  const [activeTab, setActiveTab] = useState<'leads' | 'testrides'>('leads')
  const [deleteTarget, setDeleteTarget] = useState<any>(null)
  const [followupLead, setFollowupLead] = useState<any>(null)

  const { leads, fetchLeads, isLoading: leadsLoading } = useCrmStore()
  const {
    fetchMasterData,
    leadStatuses,
    getLeadStatusName,
    isInitialized: masterInitialized
  } = useMasterStore()

  const [searchParams, setSearchParams] = useSearchParams()

  useEffect(() => {
    fetchMasterData()
    fetchLeads()
  }, [])

  // Auto-open form when navigated with ?action=new
  useEffect(() => {
    if (searchParams.get('action') === 'new') {
      setShowForm(true)
      setSearchParams({}, { replace: true })
    }
  }, [searchParams])

  const createMutation = useMutation({
    mutationFn: (data: LeadCreate) => leadsApi.create(data),
    onSuccess: (newLead) => {
      useCrmStore.getState().addLead(newLead)
      setShowForm(false)
    },
  })

  const deleteMutation = useMutation({
    mutationFn: ({ id, hardDelete }: { id: number; hardDelete?: boolean }) =>
      leadsApi.delete(id, hardDelete),
    onSuccess: () => {
      fetchLeads()
      setDeleteTarget(null)
    },
  })

  const handleDeleteConfirm = (hardDelete: boolean) => {
    if (deleteTarget) {
      deleteMutation.mutate({ id: deleteTarget.lead_id, hardDelete })
    }
  }

  const filteredLeads = leads.filter((lead) => {
    const matchesSearch =
      lead.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      lead.phone.includes(searchTerm) ||
      lead.lead_source.toLowerCase().includes(searchTerm.toLowerCase())
    const matchesStatus = statusFilter === '' || lead.lead_status_id === statusFilter
    return matchesSearch && matchesStatus
  })

  const isLoading = leadsLoading || !masterInitialized

  const getStatusColor = (statusName: string) => {
    const name = statusName.toLowerCase()
    if (name.includes('hot') || name.includes('converted')) return 'bg-green-100 text-green-800'
    if (name.includes('warm')) return 'bg-yellow-100 text-yellow-800'
    if (name.includes('cold') || name.includes('lost')) return 'bg-red-100 text-red-800'
    return 'bg-gray-100 text-gray-800'
  }

  const tabs = [
    { key: 'leads', label: 'Leads', count: leads.length },
    { key: 'testrides', label: 'Test Rides', count: null },
  ] as const

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Leads</h1>
          <p className="text-gray-500 text-sm mt-1">Manage leads and test rides</p>
        </div>

        {/* Tabs */}
        <div className="flex gap-2 bg-gray-100 p-1 rounded-lg">
          {tabs.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === tab.key
                ? 'bg-white shadow text-gray-900'
                : 'text-gray-600 hover:text-gray-900'
                }`}
            >
              {tab.label}
              {tab.count !== null && (
                <span className="ml-1 text-xs bg-gray-200 px-1.5 py-0.5 rounded-full">
                  {tab.count}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Leads Tab */}
      {activeTab === 'leads' && (
        <>
          {/* Search and Filter Bar */}
          <div className="flex flex-col sm:flex-row gap-4">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                placeholder="Search by name, phone, or source..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="input pl-10"
              />
            </div>
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value ? Number(e.target.value) : '')}
              className="input sm:w-48"
            >
              <option value="">All Status</option>
              {leadStatuses.map((status) => (
                <option key={status.status_id} value={status.status_id}>
                  {status.status_name}
                </option>
              ))}
            </select>
            <button
              onClick={() => setShowForm(true)}
              className="btn btn-primary flex items-center gap-2"
            >
              <Plus className="w-5 h-5" />
              New Lead
            </button>
          </div>

          {/* Leads Table */}
          <div className="card">
            {isLoading ? (
              <div className="text-center py-8">
                <p className="text-gray-500">Loading leads...</p>
              </div>
            ) : filteredLeads.length === 0 ? (
              <div className="text-center py-8">
                <p className="text-gray-500">No leads found</p>
                <button
                  onClick={() => setShowForm(true)}
                  className="btn btn-primary mt-4"
                >
                  Create First Lead
                </button>
              </div>
            ) : (
              <div className="table-container">
                <table className="table">
                  <thead>
                    <tr>
                      <th>S.No.</th>
                      <th>Name</th>
                      <th>Phone</th>
                      <th>Source</th>
                      <th>Status</th>
                      <th>Expected Date</th>
                      <th>Owner</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredLeads.map((lead, index) => {
                      const statusName = getLeadStatusName(lead.lead_status_id)
                      return (
                        <tr key={lead.lead_id}>
                          <td className="text-gray-500 text-center">{index + 1}</td>
                          <td className="font-medium">{lead.name}</td>
                          <td>{lead.phone}</td>
                          <td className="text-gray-600">{lead.lead_source}</td>
                          <td>
                            <span className={`px-2 py-1 text-xs rounded-full ${getStatusColor(statusName)}`}>
                              {statusName}
                            </span>
                          </td>
                          <td>{lead.expected_purchase_date ? formatDate(lead.expected_purchase_date) : '-'}</td>
                          <td className="text-gray-600">{lead.owner_staff_id || 'Unassigned'}</td>
                          <td>
                            <div className="flex gap-2">
                              <button
                                onClick={() => setSelectedLead(lead)}
                                className="p-1 text-gray-500 hover:text-blue-600"
                                title="View Details"
                              >
                                <Eye className="w-4 h-4" />
                              </button>
                              <button
                                onClick={() => setFollowupLead(lead)}
                                className="p-1 text-gray-500 hover:text-indigo-600"
                                title="Log Follow-up"
                              >
                                <ClipboardList className="w-4 h-4" />
                              </button>
                              <button
                                onClick={() => setConvertingLead(lead)}
                                className={`p-1 ${(lead as any).is_converted ? 'text-gray-300 cursor-not-allowed' : 'text-gray-500 hover:text-green-600'}`}
                                title={(lead as any).is_converted ? 'Already Converted' : 'Convert to Customer'}
                                disabled={(lead as any).is_converted}
                              >
                                <UserPlus className="w-4 h-4" />
                              </button>
                              <button
                                onClick={() => setDeleteTarget(lead)}
                                className="p-1 text-gray-500 hover:text-red-600"
                                title="Delete Lead"
                              >
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      )
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Lead Form Modal */}
          {showForm && (
            <LeadForm
              onSubmit={(data) => createMutation.mutate(data)}
              onClose={() => setShowForm(false)}
              isLoading={createMutation.isPending}
            />
          )}

          {/* Lead Conversion Modal */}
          {convertingLead && (
            <LeadConversionModal
              lead={convertingLead}
              onClose={() => setConvertingLead(null)}
              onSuccess={() => {
                setConvertingLead(null)
                fetchLeads()
              }}
            />
          )}

          {/* Lead Follow-up Modal */}
          {followupLead && (
            <LeadFollowupModal
              leadId={followupLead.lead_id}
              leadName={followupLead.name}
              onClose={() => setFollowupLead(null)}
            />
          )}

          {/* New Lead Details Dashboard Modal */}
          {selectedLead && (
            <LeadDetailsModal
              leadId={selectedLead.lead_id}
              onClose={() => {
                setSelectedLead(null)
                fetchLeads()
              }}
            />
          )}

          <DeleteConfirmModal
            isOpen={!!deleteTarget}
            onClose={() => setDeleteTarget(null)}
            onConfirm={handleDeleteConfirm}
            itemName={deleteTarget?.name || ''}
            isPending={deleteMutation.isPending}
          />
        </>
      )}

      {/* Test Rides Tab */}
      {activeTab === 'testrides' && (
        <div className="card">
          <TestRideList />
        </div>
      )}
    </div>
  )
}

import { useState } from 'react'
import { useMutation, useQueryClient, useQuery } from '@tanstack/react-query'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { financeApi, FinanceCreate } from '../api/financeApi'
import { DollarSign, X, Trash2, Search } from 'lucide-react'
import { salesApi } from '@/modules/sales/api/salesApi'
import { formatDate, formatCurrency } from '@/lib/utils'
import DeleteConfirmModal from '@/components/ui/DeleteConfirmModal'

export default function FinancePage() {
  const [showForm, setShowForm] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<any | null>(null)
  const [searchTerm, setSearchTerm] = useState('')
  const queryClient = useQueryClient()

  const { data: sales = [] } = useQuery({
    queryKey: ['sales'],
    queryFn: () => salesApi.getSales(),
  })

  // Backend doesn't have list endpoint yet, but let's assume it might or just use sales with finance
  const { data: financeRecords = [], isLoading } = useQuery({
    queryKey: ['finance-records'],
    queryFn: () => financeApi.getFinances ? financeApi.getFinances() : Promise.resolve([]),
  })

  const createMutation = useMutation({
    mutationFn: (data: FinanceCreate) => financeApi.createFinance(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['finance-records'] })
      setShowForm(false)
    },
  })

  const deleteMutation = useMutation({
    mutationFn: ({ id, hardDelete }: { id: number; hardDelete?: boolean }) =>
      financeApi.deleteFinance(id, hardDelete),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['finance-records'] })
      setDeleteTarget(null)
    },
  })

  const handleDeleteConfirm = (hardDelete: boolean) => {
    if (deleteTarget) {
      deleteMutation.mutate({ id: deleteTarget.finance_id, hardDelete })
    }
  }

  const filteredRecords = financeRecords.filter((r: any) =>
    r.bank_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.sale_id.toString().includes(searchTerm)
  )

  const handleSubmit = (data: FinanceCreate) => {
    createMutation.mutate(data)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Finance</h1>
          <p className="text-gray-600 mt-1">Manage vehicle financing</p>
        </div>
        <button onClick={() => setShowForm(true)} className="btn btn-primary flex items-center gap-2">
          <DollarSign className="w-5 h-5" />
          Create Finance Record
        </button>
      </div>

      <div className="card">
        <div className="mb-4 flex items-center justify-between gap-4">
          <div className="relative max-w-md flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search by bank or sale ID..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="input pl-10"
            />
          </div>
        </div>

        {isLoading ? (
          <div className="text-center py-12">
            <p className="text-gray-500">Loading finance records...</p>
          </div>
        ) : filteredRecords.length === 0 ? (
          <div className="text-center py-12">
            <DollarSign className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-gray-900 mb-2">No Finance Records</h2>
            <p className="text-gray-600 mb-6">Create finance records for vehicle sales.</p>
          </div>
        ) : (
          <div className="table-container">
            <table className="table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Sale ID</th>
                  <th>Financer</th>
                  <th>Loan Amount</th>
                  <th>Down Payment</th>
                  <th>Date</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredRecords.map((r: any) => (
                  <tr key={r.finance_id}>
                    <td>#{r.finance_id}</td>
                    <td className="font-medium">Sale #{r.sale_id}</td>
                    <td>{r.financer_name}</td>
                    <td className="font-semibold text-primary-700">{formatCurrency(r.loan_amount)}</td>
                    <td>{formatCurrency(r.down_payment)}</td>
                    <td>{formatDate(r.created_at)}</td>
                    <td>
                      <button
                        onClick={() => setDeleteTarget(r)}
                        className="p-2 text-red-600 hover:bg-red-50 rounded transition-colors"
                        title="Delete record"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showForm && (
        <FinanceForm
          sales={sales}
          onSubmit={handleSubmit}
          onClose={() => setShowForm(false)}
          isLoading={createMutation.isPending}
        />
      )}

      <DeleteConfirmModal
        isOpen={!!deleteTarget}
        onClose={() => setDeleteTarget(null)}
        onConfirm={handleDeleteConfirm}
        itemName={deleteTarget ? `Finance record for Sale #${deleteTarget.sale_id}` : ''}
        isPending={deleteMutation.isPending}
      />
    </div>
  )
}

interface FinanceFormProps {
  sales: any[]
  onSubmit: (data: FinanceCreate) => void
  onClose: () => void
  isLoading?: boolean
}

