import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { insuranceApi, PolicyCreate, InsuranceCompanyCreate } from '../api/insuranceApi'
import { Plus, Search, Building2, Trash2 } from 'lucide-react'
import { formatDate, formatCurrency } from '@/lib/utils'
import PolicyForm from '../components/PolicyForm'
import { useForm } from 'react-hook-form'
import { X } from 'lucide-react'
import DeleteConfirmModal from '@/components/ui/DeleteConfirmModal'

export default function InsurancePage() {
  const [searchTerm, setSearchTerm] = useState('')
  const [showPolicyForm, setShowPolicyForm] = useState(false)
  const [showCompanyForm, setShowCompanyForm] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<{ type: 'policy' | 'company'; id: number; name: string } | null>(null)
  const queryClient = useQueryClient()

  const { data: policies = [], isLoading: policiesLoading } = useQuery({
    queryKey: ['policies'],
    queryFn: insuranceApi.getPolicies,
  })

  const { data: companies = [] } = useQuery({
    queryKey: ['insurance-companies'],
    queryFn: insuranceApi.getCompanies,
  })

  const createPolicyMutation = useMutation({
    mutationFn: (data: PolicyCreate) => insuranceApi.createPolicy(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['policies'] })
      setShowPolicyForm(false)
    },
  })

  const createCompanyMutation = useMutation({
    mutationFn: (data: InsuranceCompanyCreate) => insuranceApi.createCompany(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['insurance-companies'] })
      setShowCompanyForm(false)
    },
  })

  const deleteMutation = useMutation({
    mutationFn: ({ type, id, hardDelete }: { type: 'policy' | 'company'; id: number; hardDelete?: boolean }) =>
      type === 'policy' ? insuranceApi.deletePolicy(id, hardDelete) : insuranceApi.deleteCompany(id, hardDelete),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [deleteTarget?.type === 'policy' ? 'policies' : 'insurance-companies'] })
      setDeleteTarget(null)
    },
  })

  const handleDeleteConfirm = (hardDelete: boolean) => {
    if (deleteTarget) {
      deleteMutation.mutate({ type: deleteTarget.type, id: deleteTarget.id, hardDelete })
    }
  }

  const filteredPolicies = policies.filter((policy) =>
    policy.policy_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
    policy.chassis_no.toLowerCase().includes(searchTerm.toLowerCase())
  )

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Insurance</h1>
          <p className="text-gray-600 mt-1">Manage insurance policies</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setShowCompanyForm(true)}
            className="btn btn-secondary flex items-center gap-2"
          >
            <Building2 className="w-5 h-5" />
            Add Company
          </button>
          <button onClick={() => setShowPolicyForm(true)} className="btn btn-primary flex items-center gap-2">
            <Plus className="w-5 h-5" />
            New Policy
          </button>
        </div>
      </div>

      <div className="card">
        <div className="mb-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search policies..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="input pl-10"
            />
          </div>
        </div>

        {policiesLoading ? (
          <div className="text-center py-8">
            <p className="text-gray-500">Loading policies...</p>
          </div>
        ) : filteredPolicies.length === 0 ? (
          <div className="text-center py-8">
            <p className="text-gray-500">No policies found</p>
          </div>
        ) : (
          <div className="table-container">
            <table className="table">
              <thead>
                <tr>
                  <th>Policy No</th>
                  <th>Chassis No</th>
                  <th>Start Date</th>
                  <th>End Date</th>
                  <th>Premium</th>
                  <th>Status</th>
                  <th>Created</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredPolicies.map((policy) => (
                  <tr key={policy.policy_id}>
                    <td className="font-medium">{policy.policy_number}</td>
                    <td>{policy.chassis_no}</td>
                    <td>{formatDate(policy.policy_start_date)}</td>
                    <td>{formatDate(policy.policy_end_date)}</td>
                    <td>{policy.premium_amount ? formatCurrency(policy.premium_amount) : '-'}</td>
                    <td>
                      <span className={`px-2 py-1 text-xs rounded-full ${policy.is_active
                          ? 'bg-green-100 text-green-800'
                          : 'bg-gray-100 text-gray-800'
                        }`}>
                        {policy.is_active ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                    <td>{formatDate(policy.created_at)}</td>
                    <td>
                      <button
                        onClick={() => setDeleteTarget({ type: 'policy', id: policy.policy_id, name: policy.policy_number })}
                        className="p-2 text-red-600 hover:bg-red-50 rounded"
                        title="Delete Policy"
                      >
                        <Trash2 className="w-4 h-4" />
