                                <td className="px-4 py-2">{index + 1}</td>
                                <td className="px-4 py-2">{new Date(p.invoice_date).toLocaleDateString()}</td>
                                <td className="px-4 py-2">{p.vendor_name || '-'}</td>
                                <td className="px-4 py-2">{p.invoice_number}</td>
                                <td className="px-4 py-2 text-right">₹{Number(p.invoice_amount || 0).toFixed(2)}</td>
                                <td className="px-4 py-2 text-right">{p.details?.length || 0}</td>
                                <td className="px-4 py-2">
                                    {isVoided ? (
                                        <span className="px-2 py-1 text-xs rounded-full bg-red-100 text-red-700 font-medium">Voided</span>
                                    ) : (
                                        <span className="px-2 py-1 text-xs rounded-full bg-green-100 text-green-700 font-medium">Active</span>
                                    )}
                                </td>
                                <td className="px-4 py-2 text-right">
                                    {!isVoided && (
                                        <button
                                            onClick={(e) => { e.stopPropagation(); onSetDelete({ type: 'vehicle', id: p.vehicle_purchase_id, name: `Vehicle Purchase #${index + 1}` }) }}
                                            className="p-1 text-red-500 hover:bg-red-50 rounded"
                                            title="Void Purchase"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    )}
                                </td>
                            </tr>
                        )
                    })}
                    {purchases.length === 0 && (
                        <tr>
                            <td colSpan={8} className="text-center py-8 text-gray-500">No vehicle purchases found</td>
                        </tr>
                    )}
                </tbody>
            </table>
        </div>
    )
}

import { useState, useMemo } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { X, DollarSign } from 'lucide-react'
import { salesApi, SaleCreatePayload } from '../api/salesApi'
import { masterApi } from '../../master/api/masterApi'

interface NewSaleModalProps {
    onClose: () => void
}

export default function NewSaleModal({ onClose }: NewSaleModalProps) {
    const queryClient = useQueryClient()
    const [error, setError] = useState<string | null>(null)

    // Form state
    const [customerId, setCustomerId] = useState<number | ''>('')
    const [chassisNo, setChassisNo] = useState('')
    const [saleDate, setSaleDate] = useState(new Date().toISOString().slice(0, 10))
    const [basePrice, setBasePrice] = useState<number | ''>('')
    const [taxes, setTaxes] = useState<number | ''>(0)
    const [totalAmount, setTotalAmount] = useState<number | ''>('')
    const [paymentMode, setPaymentMode] = useState('CASH')
    const [financierName, setFinancierName] = useState('')
    const [downPayment, setDownPayment] = useState<number | ''>('')
    const [remarks, setRemarks] = useState('')

    // Fetch customers + vehicles
    const { data: customers = [] } = useQuery({
        queryKey: ['customers'],
        queryFn: masterApi.getCustomers,
    })

    const { data: allVehicles = [] } = useQuery({
        queryKey: ['vehicles'],
        queryFn: () => masterApi.getVehicles(),
    })

    // Filter vehicles to only AVAILABLE / IN_STOCK
    const availableVehicles = useMemo(
        () => allVehicles.filter((v: any) => v.current_status === 'IN_STOCK' || v.current_status === 'AVAILABLE'),
        [allVehicles]
    )

    // Auto-calculate total when base_price or taxes change
    const computedTotal = useMemo(() => {
        const bp = Number(basePrice) || 0
        const tx = Number(taxes) || 0
        return bp + tx
    }, [basePrice, taxes])

    // Sync total
    const handleBasePriceChange = (val: number | '') => {
        setBasePrice(val)
        setTotalAmount((Number(val) || 0) + (Number(taxes) || 0))
    }
    const handleTaxesChange = (val: number | '') => {
        setTaxes(val)
        setTotalAmount((Number(basePrice) || 0) + (Number(val) || 0))
    }

    const mutation = useMutation({
        mutationFn: (payload: SaleCreatePayload) => salesApi.createSaleBilling(payload),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['sales'] })
            queryClient.invalidateQueries({ queryKey: ['vehicles'] })
            queryClient.invalidateQueries({ queryKey: ['customers'] })
            onClose()
        },
        onError: (err: any) => {
            setError(err?.response?.data?.detail || 'Failed to create sale.')
        },
    })

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault()
        setError(null)

        if (!customerId) { setError('Please select a customer.'); return }
        if (!chassisNo) { setError('Please select a vehicle.'); return }
        if (!basePrice || Number(basePrice) <= 0) { setError('Base Price must be > 0.'); return }
        if (!totalAmount || Number(totalAmount) <= 0) { setError('Total Amount must be > 0.'); return }
        if (paymentMode === 'FINANCE' && !financierName.trim()) { setError('Financier Name is required for FINANCE mode.'); return }

        mutation.mutate({
            customer_id: customerId as number,
            chassis_no: chassisNo,
            sale_date: saleDate,
            base_price: Number(basePrice),
            taxes: Number(taxes) || 0,
            total_amount: Number(totalAmount),
            payment_mode: paymentMode,
            financier_name: paymentMode === 'FINANCE' ? financierName.trim() : undefined,
            down_payment_amount: Number(downPayment) || 0,
            remarks: remarks.trim() || undefined,
            is_direct_sale: true,
        })
    }

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-3xl max-h-[90vh] overflow-y-auto">
                <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between z-10">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-100 text-blue-600 rounded-lg">
                            <DollarSign className="w-5 h-5" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-gray-900">New Sale / Billing</h2>
                            <p className="text-sm text-gray-500">Create sale, generate invoice, and record payment</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-6">
                    {/* ── Customer & Vehicle ── */}
                    <fieldset>
                        <legend className="text-sm font-semibold text-gray-900 mb-3 uppercase tracking-wider">
                            Customer & Vehicle
                        </legend>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Customer <span className="text-red-500">*</span>
                                </label>
                                <select
                                    required
                                    value={customerId}
                                    onChange={(e) => setCustomerId(e.target.value ? Number(e.target.value) : '')}
                                    className="input"
                                >
                                    <option value="">Select customer</option>
                                    {customers.map((c: any) => (
                                        <option key={c.customer_id} value={c.customer_id}>
                                            {c.name} — {c.primary_phone}
                                        </option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Vehicle (Available) <span className="text-red-500">*</span>
                                </label>
                                <select
                                    required
                                    value={chassisNo}
                                    onChange={(e) => setChassisNo(e.target.value)}
                                    className="input"
                                >
                                    <option value="">Select vehicle</option>
                                    {availableVehicles.map((v: any) => (
                                        <option key={v.chassis_no} value={v.chassis_no}>
                                            {v.model?.model_name || 'Vehicle'} — {v.chassis_no} ({v.color || 'N/A'})
                                        </option>
                                    ))}
                                </select>
                                {availableVehicles.length === 0 && (
                                    <p className="text-xs text-amber-600 mt-1">No available vehicles in inventory.</p>
                                )}
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Sale Date</label>
                                <input
                                    type="date"
                                    value={saleDate}
                                    onChange={(e) => setSaleDate(e.target.value)}
                                    className="input"
                                />
                            </div>
                        </div>
                    </fieldset>

                    {/* ── Financials ── */}
                    <fieldset>
                        <legend className="text-sm font-semibold text-gray-900 mb-3 uppercase tracking-wider">
                            Financials
                        </legend>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Base Price (₹) <span className="text-red-500">*</span>
                                </label>
                                <input
                                    type="number"
                                    required
                                    min={1}
                                    value={basePrice}
                                    onChange={(e) => handleBasePriceChange(e.target.value ? Number(e.target.value) : '')}
                                    className="input"
                                    placeholder="0"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Taxes (₹)</label>
                                <input
                                    type="number"
                                    min={0}
                                    value={taxes}
                                    onChange={(e) => handleTaxesChange(e.target.value ? Number(e.target.value) : '')}
                                    className="input"
                                    placeholder="0"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Total Amount (₹) <span className="text-red-500">*</span>
                                </label>
                                <input
                                    type="number"
                                    required
                                    min={1}
                                    value={totalAmount}
                                    onChange={(e) => setTotalAmount(e.target.value ? Number(e.target.value) : '')}
                                    className="input font-semibold"
                                />
                                {computedTotal > 0 && totalAmount !== computedTotal && (
                                    <p className="text-xs text-amber-600 mt-1">Auto-calculated: ₹{computedTotal.toLocaleString()}</p>
                                )}
                            </div>
                        </div>
                    </fieldset>

                    {/* ── Payment ── */}
                    <fieldset>
                        <legend className="text-sm font-semibold text-gray-900 mb-3 uppercase tracking-wider">
                            Payment
                        </legend>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    Payment Mode <span className="text-red-500">*</span>
                                </label>
                                <select
                                    required
                                    value={paymentMode}
                                    onChange={(e) => setPaymentMode(e.target.value)}
                                    className="input"
                                >
                                    <option value="CASH">Cash</option>
                                    <option value="CARD">Card</option>
                                    <option value="UPI">UPI</option>
                                    <option value="FINANCE">Finance</option>
                                </select>
                            </div>
                            {paymentMode === 'FINANCE' && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">
                                        Financier Name <span className="text-red-500">*</span>
                                    </label>
                                    <input
                                        type="text"
                                        required
                                        value={financierName}
                                        onChange={(e) => setFinancierName(e.target.value)}
                                        className="input"
                                        placeholder="e.g. HDFC, Bajaj Finance"
                                    />
                                </div>
                            )}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Down Payment (₹)</label>
                                <input
                                    type="number"
                                    min={0}
                                    value={downPayment}
                                    onChange={(e) => setDownPayment(e.target.value ? Number(e.target.value) : '')}
                                    className="input"
                                    placeholder="0"
                                />
                            </div>
                        </div>
                    </fieldset>

                    {/* Remarks */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Remarks</label>
                        <textarea
                            value={remarks}
                            onChange={(e) => setRemarks(e.target.value)}
                            className="input"
                            rows={2}
                            placeholder="Optional notes"
                        />
                    </div>

                    {/* Error */}
                    {error && (
                        <div className="p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700">
                            {error}
                        </div>
                    )}

                    {/* Actions */}
                    <div className="flex justify-end gap-3 pt-4 border-t">
                        <button type="button" onClick={onClose} className="btn btn-secondary">
                            Cancel
                        </button>
                        <button type="submit" disabled={mutation.isPending} className="btn btn-primary">
                            {mutation.isPending ? 'Processing...' : 'Create Sale & Invoice'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    )
}

import { useState } from 'react'
import { X } from 'lucide-react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import { salesApi } from '../api/salesApi'
import toast from 'react-hot-toast'

interface PaymentModalProps {
    saleId: number
    onClose: () => void
}

const PAYMENT_TYPES = ['BOOKING', 'PARTIAL', 'FINAL'] as const
const PAYMENT_MODES = ['CASH', 'UPI', 'CARD', 'CHEQUE', 'FINANCE'] as const

export default function PaymentModal({ saleId, onClose }: PaymentModalProps) {
    const queryClient = useQueryClient()
    const [paymentType, setPaymentType] = useState('BOOKING')
    const [paymentMode, setPaymentMode] = useState('CASH')
    const [amount, setAmount] = useState('')
    const [referenceNumber, setReferenceNumber] = useState('')
    const [bankName, setBankName] = useState('')
    const [remarks, setRemarks] = useState('')

    const mutation = useMutation({
        mutationFn: () =>
            salesApi.addPayment(saleId, {
                payment_type: paymentType,
                payment_mode: paymentMode,
                amount: parseFloat(amount),
                reference_number: referenceNumber || undefined,
                bank_name: bankName || undefined,
                remarks: remarks || undefined,
            }),
        onSuccess: () => {
            toast.success('Payment added successfully')
            queryClient.invalidateQueries({ queryKey: ['sale', String(saleId)] })
            queryClient.invalidateQueries({ queryKey: ['sale-progress', String(saleId)] })
            onClose()
        },
        onError: (err: any) => {
            toast.error(err?.response?.data?.detail || 'Failed to add payment')
        },
    })

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault()
        if (!amount || parseFloat(amount) <= 0) {
            toast.error('Please enter a valid amount')
            return
        }
        mutation.mutate()
    }

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-lg max-w-lg w-full">
                <div className="flex items-center justify-between px-6 py-4 border-b">
                    <h2 className="text-lg font-semibold">Add Payment</h2>
                    <button onClick={onClose} className="p-1 hover:bg-gray-100 rounded">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Payment Type *</label>
                            <select
                                value={paymentType}
                                onChange={(e) => setPaymentType(e.target.value)}
                                className="input"
                            >
                                {PAYMENT_TYPES.map((t) => (
                                    <option key={t} value={t}>{t}</option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Payment Mode *</label>
                            <select
                                value={paymentMode}
                                onChange={(e) => setPaymentMode(e.target.value)}
                                className="input"
                            >
                                {PAYMENT_MODES.map((m) => (
                                    <option key={m} value={m}>{m}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Amount (₹) *</label>
                        <input
                            type="number"
                            step="0.01"
                            min="1"
                            value={amount}
                            onChange={(e) => setAmount(e.target.value)}
                            className="input"
                            placeholder="Enter amount"
                            required
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Reference / Transaction Number</label>
                        <input
                            type="text"
                            value={referenceNumber}
                            onChange={(e) => setReferenceNumber(e.target.value)}
                            className="input"
                            placeholder="UTR, cheque number, etc."
                        />
                    </div>

                    {paymentMode === 'FINANCE' && (
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Bank Name</label>
                            <input
                                type="text"
                                value={bankName}
                                onChange={(e) => setBankName(e.target.value)}
                                className="input"
                                placeholder="Finance bank name"
                            />
                        </div>
                    )}

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Remarks</label>
                        <textarea
                            value={remarks}
                            onChange={(e) => setRemarks(e.target.value)}
                            className="input"
                            rows={2}
                            placeholder="Optional notes"
                        />
                    </div>

                    <div className="flex justify-end gap-3 pt-2 border-t">
                        <button type="button" onClick={onClose} className="btn btn-secondary">
                            Cancel
                        </button>
                        <button type="submit" disabled={mutation.isPending} className="btn btn-primary">
                            {mutation.isPending ? 'Adding...' : 'Add Payment'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    )
}

import { useState, useEffect } from 'react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import { Sale, DeliveryChecklist, salesApi } from '../api/salesApi'

interface Props {
    sale: Sale
}

export default function PostDeliveryChecklist({ sale }: Props) {
    const queryClient = useQueryClient()
    const [checklist, setChecklist] = useState<Partial<DeliveryChecklist>>({})

    useEffect(() => {
        if (sale.delivery_checklist) {
            setChecklist(sale.delivery_checklist)
        }
    }, [sale.delivery_checklist])

    const updateMutation = useMutation({
        mutationFn: (data: Partial<DeliveryChecklist>) =>
            salesApi.updateChecklist(sale.sale_id, data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['sale', String(sale.sale_id)] })
            alert("Checklist updated successfully")
        },
        onError: (error: any) => {
            alert("Failed to update checklist: " + (error?.response?.data?.detail || error.message))
        }
    })

    const handleChange = (field: keyof DeliveryChecklist, value: any) => {
        setChecklist(prev => ({ ...prev, [field]: value }))
    }

    const handleSave = () => {
        updateMutation.mutate(checklist)
    }

    const sections = [
        {
            title: "Insurance",
            checked: checklist.insurance_completed,
            onCheck: (v: boolean) => handleChange('insurance_completed', v),
            details: checklist.insurance_details,
            onDetails: (v: string) => handleChange('insurance_details', v),
            detailsLabel: "Policy Details"
        },
        {
            title: "Subsidy Portal",
            checked: checklist.subsidy_completed,
            onCheck: (v: boolean) => handleChange('subsidy_completed', v),
            details: checklist.subsidy_details,
            onDetails: (v: string) => handleChange('subsidy_details', v),
            detailsLabel: "Application Details"
        },
        {
            title: "RTO Portal",
            checked: checklist.rto_completed,
            onCheck: (v: boolean) => handleChange('rto_completed', v),
            details: checklist.rto_details,
            onDetails: (v: string) => handleChange('rto_details', v),
            detailsLabel: "Registration Details"
        },
        {
            title: "Celex Portal (Number Plate)",
            checked: checklist.celex_plate_ordered,
            onCheck: (v: boolean) => handleChange('celex_plate_ordered', v),
            details: checklist.celex_details,
            onDetails: (v: string) => handleChange('celex_details', v),
            detailsLabel: "Order Details"
        },
        {
            title: "Celex Portal (Subsidy Papers)",
            checked: checklist.celex_subsidy_completed,
            onCheck: (v: boolean) => handleChange('celex_subsidy_completed', v),
            // No details for this one specifically requested, but maybe share celex_details? 
            // Or leave details specific to this task out if not needed.
            // Let's hide details input for this one if unnecessary.
            details: undefined,
            onDetails: undefined,
        }
    ]

    return (
        <div className="card mt-6">
            <h2 className="text-xl font-semibold mb-4 text-blue-800">Post-Delivery Compliance</h2>
            <p className="text-sm text-gray-600 mb-4">
                Track optional compliance tasks. These do not block delivery.
            </p>

            <div className="space-y-6">
                {sections.map((section, idx) => (
                    <div key={idx} className="p-4 bg-gray-50 rounded border border-gray-200">
                        <div className="flex items-center gap-3 mb-3">
                            <input
                                type="checkbox"
                                checked={!!section.checked}
                                onChange={(e) => section.onCheck(e.target.checked)}
                                className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500"
                            />
                            <span className={`font-medium ${section.checked ? 'text-green-700' : 'text-gray-700'}`}>
                                {section.title}
                            </span>
                            {section.checked && <span className="text-xs bg-green-100 text-green-800 px-2 py-0.5 rounded">Completed</span>}
                        </div>
                        {section.onDetails && (
                            <div className="ml-8">
                                <label className="text-xs text-gray-500 block mb-1">{section.detailsLabel}</label>
                                <textarea
                                    value={section.details || ''}
                                    onChange={(e) => section.onDetails!(e.target.value)}
                                    className="w-full text-sm p-2 border rounded"
                                    placeholder={`Enter ${section.detailsLabel.toLowerCase()}...`}
                                    rows={2}
                                />
                            </div>
                        )}
                    </div>
                ))}

                <div className="p-4 bg-gray-50 rounded border border-gray-200">
                    <h3 className="font-medium mb-3">Number Plate Fixation</h3>
                    <div className="flex items-center gap-4">
                        <label className="text-sm text-gray-600">Date of Fixation:</label>
                        <input
                            type="date"
                            value={checklist.plate_fixation_date || ''}
                            onChange={(e) => handleChange('plate_fixation_date', e.target.value)}
                            className="p-2 border rounded"
                        />
                    </div>
                </div>

                <div className="flex justify-end pt-4">
                    <button
                        onClick={handleSave}
                        disabled={updateMutation.isPending}
                        className="btn btn-primary"
                    >
                        {updateMutation.isPending ? 'Saving...' : 'Save Compliance Details'}
                    </button>
                </div>
            </div>
        </div>
    )
}

