      </div>

      {/* ——— Stage Advance ——— */}
      {nextStage && sale.sale_status !== 'DELIVERED' && (
        <div className="card border-l-4 border-l-indigo-500">
          <h2 className="text-lg font-semibold mb-3 flex items-center gap-2">
            <ChevronRight className="w-5 h-5 text-indigo-600" />
