          </h2>
          <div className="space-y-3">
            {docCards.map((doc) => (
              <div key={doc.key} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                <div>
                  <p className="font-medium text-sm">{doc.label}</p>
                  <p className="text-xs text-gray-500">
