                {doc.generated ? (
                  <div className="flex items-center gap-2">
                    <span className="text-green-600 text-xs font-medium bg-green-50 px-2 py-0.5 rounded-full">✓ Ready</span>
                    <button
                      onClick={() => handlePrint(doc.key)}
