            {portal.all_portals_completed && (
              <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full ml-2">All Complete</span>
            )}
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Insurance */}
            <ToggleSwitch
              checked={portal.insurance_status === 'COMPLETED'}
              onChange={(val) => updatePortalMutation.mutate({ insurance_status: val ? 'COMPLETED' : 'PENDING' })}
              disabled={updatePortalMutation.isPending}
              label="Insurance"
              icon={<Shield className="w-4 h-4" />}
              description={portal.insurance_policy_number ? `Policy: ${portal.insurance_policy_number}` : 'Vehicle insurance filing'}
            />

            {/* RTO Portal */}
            <ToggleSwitch
              checked={portal.rto_status === 'COMPLETED'}
              onChange={(val) => updatePortalMutation.mutate({ rto_status: val ? 'COMPLETED' : 'PENDING' })}
              disabled={updatePortalMutation.isPending}
              label="RTO Portal"
              icon={<Car className="w-4 h-4" />}
              description={portal.registration_number ? `Reg: ${portal.registration_number}` : 'Vehicle registration'}
            />

            {/* Subsidy Portal */}
            <ToggleSwitch
              checked={portal.subsidy_status === 'COMPLETED'}
              onChange={(val) => updatePortalMutation.mutate({ subsidy_status: val ? 'COMPLETED' : 'PENDING' })}
              disabled={updatePortalMutation.isPending}
              label="Subsidy Portal"
              icon={<Landmark className="w-4 h-4" />}
              description={portal.subsidy_reference ? `Ref: ${portal.subsidy_reference}` : 'Government subsidy application'}
            />

            {/* CELEX / Number Plate Ordered */}
            <ToggleSwitch
              checked={portal.celex_status === 'COMPLETED'}
              onChange={(val) => updatePortalMutation.mutate({ celex_status: val ? 'COMPLETED' : 'PENDING' })}
              disabled={updatePortalMutation.isPending}
              label="Number Plate Ordered"
              icon={<Hash className="w-4 h-4" />}
              description={portal.number_plate_ordered_date ? `Ordered: ${formatDate(portal.number_plate_ordered_date)}` : 'CELEX number plate order'}
            />
          </div>

          {/* Number Plate Affixed — with date picker */}
          <div className="mt-4">
            <ToggleSwitch
              checked={!!portal.number_plate_fixed_date}
              onChange={(val) => {
                if (val) {
                  updatePortalMutation.mutate({ number_plate_fixed_date: new Date().toISOString().slice(0, 10) as any })
                } else {
                  updatePortalMutation.mutate({ number_plate_fixed_date: null as any })
                }
              }}
              disabled={updatePortalMutation.isPending}
              label="Number Plate Affixed"
              icon={<CalendarCheck className="w-4 h-4" />}
              description="Physical number plate has been installed on the vehicle"
            >
              {portal.number_plate_fixed_date && (
                <div className="mt-3 flex items-center gap-2 ml-11">
                  <label className="text-xs text-gray-600">Affixed Date:</label>
                  <input
                    type="date"
                    value={typeof portal.number_plate_fixed_date === 'string' ? portal.number_plate_fixed_date.slice(0, 10) : ''}
                    onChange={(e) => updatePortalMutation.mutate({ number_plate_fixed_date: e.target.value as any })}
                    className="input text-sm py-1 px-2 w-auto"
                  />
                </div>
              )}
            </ToggleSwitch>
          </div>

          {/* Form 20 / Helmet Invoice toggles */}
          <div className="grid grid-cols-2 gap-4 mt-4">
            <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg border border-gray-200">
              <input
                type="checkbox"
                checked={portal.form_20_generated}
                onChange={(e) => updatePortalMutation.mutate({ form_20_generated: e.target.checked })}
                className="w-4 h-4 rounded border-gray-300 text-green-600 focus:ring-green-500"
              />
              <span className="text-sm font-medium text-gray-700">Form 20 Generated</span>
            </div>
            <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg border border-gray-200">
              <input
                type="checkbox"
                checked={portal.helmet_invoice_generated}
                onChange={(e) => updatePortalMutation.mutate({ helmet_invoice_generated: e.target.checked })}
                className="w-4 h-4 rounded border-gray-300 text-green-600 focus:ring-green-500"
              />
              <span className="text-sm font-medium text-gray-700">Helmet Invoice Generated</span>
            </div>
          </div>
        </div>
      )}

      {/* ——— Delivery Action ——— */}
      {sale.sale_status !== 'DELIVERED' && (
        <div className="card border-t-4 border-t-blue-500">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-bold">Actions</h2>
              <p className="text-sm text-gray-600 mt-1">Complete the sale and deliver vehicle</p>
            </div>
            <button
              onClick={() => {
                if (confirm('Mark this sale as delivered?')) {
                  deliverMutation.mutate(undefined)
                }
              }}
              disabled={deliverMutation.isPending || !canDeliver}
              className={`btn btn-primary flex items-center gap-2 ${!canDeliver ? 'opacity-50 cursor-not-allowed' : ''}`}
              title={!canDeliver ? 'Generate all documents first' : ''}
            >
              <Truck className="w-5 h-5" />
              {deliverMutation.isPending ? 'Delivering...' : 'Mark as Delivered'}
            </button>
          </div>
          {!canDeliver && (
            <div className="mt-3 text-sm text-red-500 bg-red-50 p-2 rounded">
              Documents Pending:
              {!documents.invoice && ' Invoice,'}
              {!documents.receipt && ' Receipt,'}
              {!documents.challan && ' Challan,'}
              {!documents.service_schedule && ' Service Schedule,'}
            </div>
          )}
        </div>
      )}

      {/* ——— Post-Delivery Checklist ——— */}
      <PostDeliveryChecklist sale={sale} />

      {/* ——— Payment Modal ——— */}
      {showPaymentModal && (
        <PaymentModal saleId={sale.sale_id} onClose={() => setShowPaymentModal(false)} />
      )}
    </div>
  )
}

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { salesApi, VehicleSaleCreate } from '../api/salesApi'
import { Plus, Search, Eye, Truck, FileText, Trash2, DollarSign } from 'lucide-react'
import { formatDate, formatCurrency } from '@/lib/utils'
import SaleForm from '../components/SaleForm'
import NewSaleModal from '../components/NewSaleModal'
import { useNavigate } from 'react-router-dom'
import DeleteConfirmModal from '@/components/ui/DeleteConfirmModal'

export default function SalesPage() {
  const [searchTerm, setSearchTerm] = useState('')
  const [statusFilter, setStatusFilter] = useState<string>('')
  const [showForm, setShowForm] = useState(false)
  const [showBillingModal, setShowBillingModal] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<any | null>(null)
  const queryClient = useQueryClient()
  const navigate = useNavigate()

  const { data: sales = [], isLoading } = useQuery({
    queryKey: ['sales', statusFilter],
    queryFn: () => salesApi.getSales(statusFilter || undefined),
  })

  const createMutation = useMutation({
    mutationFn: (data: VehicleSaleCreate) => salesApi.createSale(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['sales'] })
      setShowForm(false)
    },
  })

  const deleteMutation = useMutation({
    mutationFn: ({ id, hardDelete }: { id: number; hardDelete?: boolean }) =>
      salesApi.deleteSale(id, hardDelete),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['sales'] })
      setDeleteTarget(null)
    },
  })

  const handleDeleteConfirm = (hardDelete: boolean) => {
    if (deleteTarget) {
      deleteMutation.mutate({ id: deleteTarget.sale_id, hardDelete })
    }
  }

  const filteredSales = sales.filter((sale) =>
    sale.chassis_no?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    sale.sale_id.toString().includes(searchTerm) ||
    sale.customer?.name?.toLowerCase().includes(searchTerm.toLowerCase())
  )

  // Count by status
  const pendingCount = sales.filter(s => s.sale_status === 'PENDING' || s.sale_status === 'BOOKED').length
  const deliveredCount = sales.filter(s => s.sale_status === 'DELIVERED').length

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'DELIVERED':
        return 'bg-green-100 text-green-800'
      case 'PENDING':
      case 'BOOKED':
        return 'bg-yellow-100 text-yellow-800'
      case 'INVOICED':
        return 'bg-blue-100 text-blue-800'
      default:
        return 'bg-gray-100 text-gray-800'
    }
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Sales</h1>
          <p className="text-gray-500 text-sm mt-1">Manage vehicle sales and deliveries</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setShowBillingModal(true)} className="btn btn-primary flex items-center gap-2">
            <DollarSign className="w-5 h-5" />
            New Sale / Billing
          </button>
          <button onClick={() => setShowForm(true)} className="btn btn-secondary flex items-center gap-2">
            <Plus className="w-5 h-5" />
            Quick Sale
          </button>
        </div>
      </div>

      {/* Status Tabs */}
      <div className="flex gap-2 bg-gray-100 p-1 rounded-lg w-fit">
        <button
          onClick={() => setStatusFilter('')}
          className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${statusFilter === '' ? 'bg-white shadow text-gray-900' : 'text-gray-600 hover:text-gray-900'
            }`}
        >
          All ({sales.length})
        </button>
        <button
          onClick={() => setStatusFilter('PENDING')}
          className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${statusFilter === 'PENDING' ? 'bg-white shadow text-yellow-700' : 'text-gray-600 hover:text-gray-900'
            }`}
        >
          Pending ({pendingCount})
        </button>
        <button
          onClick={() => setStatusFilter('DELIVERED')}
          className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${statusFilter === 'DELIVERED' ? 'bg-white shadow text-green-700' : 'text-gray-600 hover:text-gray-900'
            }`}
        >
          Delivered ({deliveredCount})
        </button>
      </div>

      {/* Search Bar */}
      <div className="relative max-w-md">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
        <input
          type="text"
          placeholder="Search by sale ID, chassis, or customer..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="input pl-10"
        />
      </div>

      {/* Sales Table */}
      <div className="card">
        {isLoading ? (
          <div className="text-center py-8">
            <p className="text-gray-500">Loading sales...</p>
          </div>
        ) : filteredSales.length === 0 ? (
          <div className="text-center py-8">
            <p className="text-gray-500 mb-4">No sales found</p>
            <button onClick={() => setShowForm(true)} className="btn btn-primary">
              Create First Sale
            </button>
          </div>
        ) : (
          <div className="table-container">
            <table className="table">
              <thead>
                <tr>
                  <th>Sale ID</th>
                  <th>Customer</th>
                  <th>Vehicle</th>
                  <th>Status</th>
                  <th>Docs</th>
                  <th>Booking</th>
                  <th>Date</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredSales.map((sale) => {
                  // Count completed documents
                  const docsReady = [
                    sale.receipts && sale.receipts.length > 0,
                    sale.invoice_number,
                    sale.challan_number,
                    sale.is_service_schedule_generated
                  ].filter(Boolean).length

                  return (
                    <tr key={sale.sale_id}>
                      <td className="font-medium">#{sale.sale_id}</td>
                      <td>{sale.customer?.name || '-'}</td>
                      <td>
                        <div>
                          <span className="font-medium">{sale.vehicle?.model?.model_name || '-'}</span>
                          <span className="text-xs text-gray-500 block">{sale.chassis_no}</span>
                        </div>
                      </td>
                      <td>
                        <span className={`px-2 py-1 text-xs rounded-full ${getStatusBadge(sale.sale_status)}`}>
                          {sale.sale_status}
                        </span>
                      </td>
                      <td>
                        <span className={`text-sm ${docsReady === 4 ? 'text-green-600' : 'text-gray-500'}`}>
                          {docsReady}/4
                        </span>
                      </td>
                      <td>{formatCurrency(sale.booking_amount || 0)}</td>
                      <td>{formatDate(sale.created_at)}</td>
                      <td>
                        <div className="flex items-center gap-1">
                          <button
                            onClick={() => navigate(`/sales/${sale.sale_id}`)}
                            className="p-2 text-blue-600 hover:bg-blue-50 rounded"
                            title="View Details"
                          >
                            <Eye className="w-4 h-4" />
                          </button>
                          {sale.sale_status !== 'DELIVERED' && (
                            <button
                              onClick={() => navigate(`/sales/${sale.sale_id}`)}
                              className="p-2 text-green-600 hover:bg-green-50 rounded"
                              title="Process Delivery"
                            >
                              <Truck className="w-4 h-4" />
                            </button>
                          )}
                          <button
                            onClick={() => setDeleteTarget(sale)}
                            className="p-2 text-red-600 hover:bg-red-50 rounded"
                            title="Delete Sale"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Sale Form Modal */}
      {showForm && (
        <SaleForm
          onSubmit={(data) => createMutation.mutate(data)}
          onClose={() => setShowForm(false)}
          isLoading={createMutation.isPending}
        />
      )}

      {/* New Sale / Billing Modal */}
      {showBillingModal && (
        <NewSaleModal onClose={() => setShowBillingModal(false)} />
      )}

      <DeleteConfirmModal
        isOpen={!!deleteTarget}
        onClose={() => setDeleteTarget(null)}
        onConfirm={handleDeleteConfirm}
        itemName={deleteTarget ? `Sale #${deleteTarget.sale_id}` : ''}
        isPending={deleteMutation.isPending}
      />
    </div>
  )
}

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { serviceApi, JobCardCreate } from '../api/serviceApi'
import { Plus, Search, CheckCircle, Wrench, Trash2 } from 'lucide-react'
import { formatDate, formatDateTime } from '@/lib/utils'
import JobCardForm from '../components/JobCardForm'
import DeleteConfirmModal from '@/components/ui/DeleteConfirmModal'

export default function ServicePage() {
  const [searchTerm, setSearchTerm] = useState('')
  const [statusFilter, setStatusFilter] = useState<'all' | 'open' | 'closed'>('all')
  const [showForm, setShowForm] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<any | null>(null)
  const queryClient = useQueryClient()

  const { data: jobCards = [], isLoading } = useQuery({
    queryKey: ['job-cards'],
    queryFn: serviceApi.getJobCards,
  })

  const createMutation = useMutation({
    mutationFn: (data: JobCardCreate) => serviceApi.createJobCard(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['job-cards'] })
      setShowForm(false)
    },
  })

  const closeMutation = useMutation({
    mutationFn: (jobCardId: number) => serviceApi.closeJobCard(jobCardId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['job-cards'] })
    },
  })

  const deleteMutation = useMutation({
    mutationFn: ({ id, hardDelete }: { id: number; hardDelete?: boolean }) =>
      serviceApi.deleteJobCard(id, hardDelete),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['job-cards'] })
      setDeleteTarget(null)
    },
  })

  const handleDeleteConfirm = (hardDelete: boolean) => {
    if (deleteTarget) {
      deleteMutation.mutate({ id: deleteTarget.job_card_id, hardDelete })
    }
  }

  // Status counts
  const openCount = jobCards.filter((j: any) => !j.out_datetime).length
  const closedCount = jobCards.filter((j: any) => j.out_datetime).length

  const filteredJobCards = jobCards.filter((job: any) => {
    const matchesSearch =
      job.job_card_no?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      job.chassis_no?.toLowerCase().includes(searchTerm.toLowerCase())

    const matchesStatus =
      statusFilter === 'all' ||
      (statusFilter === 'open' && !job.out_datetime) ||
      (statusFilter === 'closed' && job.out_datetime)

    return matchesSearch && matchesStatus
  })

  const handleClose = (jobCardId: number) => {
    if (confirm('Close this job card?')) {
      closeMutation.mutate(jobCardId)
    }
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Service</h1>
          <p className="text-gray-500 text-sm mt-1">Manage service job cards</p>
        </div>
        <button onClick={() => setShowForm(true)} className="btn btn-primary flex items-center gap-2">
          <Plus className="w-5 h-5" />
          New Job Card
        </button>
      </div>

      {/* Status Tabs */}
      <div className="flex gap-2 bg-gray-100 p-1 rounded-lg w-fit">
        <button
          onClick={() => setStatusFilter('all')}
          className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${statusFilter === 'all' ? 'bg-white shadow text-gray-900' : 'text-gray-600 hover:text-gray-900'
            }`}
        >
          All ({jobCards.length})
        </button>
        <button
          onClick={() => setStatusFilter('open')}
          className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${statusFilter === 'open' ? 'bg-white shadow text-yellow-700' : 'text-gray-600 hover:text-gray-900'
            }`}
        >
          Open ({openCount})
        </button>
        <button
          onClick={() => setStatusFilter('closed')}
          className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${statusFilter === 'closed' ? 'bg-white shadow text-green-700' : 'text-gray-600 hover:text-gray-900'
            }`}
        >
          Closed ({closedCount})
        </button>
      </div>

      {/* Search */}
      <div className="relative max-w-md">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
        <input
          type="text"
          placeholder="Search by job card or chassis..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="input pl-10"
        />
      </div>

      {/* Job Cards Table */}
      <div className="card">
        {isLoading ? (
          <div className="text-center py-8">
            <p className="text-gray-500">Loading job cards...</p>
          </div>
        ) : filteredJobCards.length === 0 ? (
          <div className="text-center py-8">
            <Wrench className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-500 mb-4">No job cards found</p>
            <button onClick={() => setShowForm(true)} className="btn btn-primary">
              Create First Job Card
            </button>
          </div>
        ) : (
          <div className="table-container">
            <table className="table">
              <thead>
                <tr>
                  <th>Job Card No</th>
                  <th>Chassis No</th>
                  <th>In Date/Time</th>
                  <th>Out Date/Time</th>
                  <th>Opening KM</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredJobCards.map((job: any) => (
                  <tr key={job.job_card_id}>
                    <td className="font-medium">{job.job_card_no}</td>
                    <td className="font-mono text-sm">{job.chassis_no}</td>
                    <td>{formatDateTime(job.in_datetime)}</td>
                    <td>{job.out_datetime ? formatDateTime(job.out_datetime) : '-'}</td>
                    <td>{job.opening_km}</td>
                    <td>
                      <span className={`px-2 py-1 text-xs rounded-full ${job.out_datetime
                        ? 'bg-green-100 text-green-800'
                        : 'bg-yellow-100 text-yellow-800'
                        }`}>
                        {job.out_datetime ? 'Closed' : 'Open'}
                      </span>
                    </td>
                    <td>
                      <div className="flex items-center gap-1">
                        {!job.out_datetime && (
                          <button
                            onClick={() => handleClose(job.job_card_id)}
                            className="p-2 text-green-600 hover:bg-green-50 rounded"
                            title="Close Job Card"
                          >
                            <CheckCircle className="w-4 h-4" />
                          </button>
                        )}
                        <button
                          onClick={() => setDeleteTarget(job)}
                          className="p-2 text-red-600 hover:bg-red-50 rounded"
                          title="Delete Job Card"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Job Card Form Modal */}
      {showForm && (
        <JobCardForm
          onSubmit={(data) => createMutation.mutate(data)}
          onClose={() => setShowForm(false)}
          isLoading={createMutation.isPending}
        />
      )}

      <DeleteConfirmModal
        isOpen={!!deleteTarget}
        onClose={() => setDeleteTarget(null)}
        onConfirm={handleDeleteConfirm}
        itemName={deleteTarget ? `Job Card ${deleteTarget.job_card_no}` : ''}
        isPending={deleteMutation.isPending}
      />
    </div>
  )
}

import { useAuthStore } from '@/store/authStore'
import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { api } from '@/lib/api'
import { Plus, Search, RotateCcw, X } from 'lucide-react'
import { formatDate } from '@/lib/utils'
import TempPinModal from '../../admin/components/TempPinModal'
import { SkeletonTable } from '@/components/ui/SkeletonTable'
import DeleteConfirmModal from '@/components/ui/DeleteConfirmModal'

interface Staff {
    staff_id: number
    full_name: string
    mobile_no: string
    email?: string
    designation: string
    is_active: boolean
    joined_date?: string
    created_at: string
    updated_at?: string
    deleted_at?: string
    is_deleted?: boolean
    deleted_by?: number
}

interface CreateStaffForm {
    full_name: string
    mobile_no: string
    email: string
    designation: string
    aadhaar_no: string
    pan_no?: string
    joined_date?: string
    address_line1?: string
    city?: string
    state?: string
    pincode?: string
    bank_name?: string
    bank_account_no?: string
    ifsc_code?: string
    upi_id?: string
    emergency_contact_name?: string
    emergency_contact_no?: string
}

const INITIAL_FORM: CreateStaffForm = {
    full_name: '',
    mobile_no: '',
    email: '',
    designation: 'STAFF',
    aadhaar_no: '',
    pan_no: '',
    joined_date: '',
    address_line1: '',
    city: '',
    state: '',
    pincode: '',
    bank_name: '',
    bank_account_no: '',
    ifsc_code: '',
    upi_id: '',
    emergency_contact_name: '',
    emergency_contact_no: '',
}

export default function StaffManager() {
    const [searchTerm, setSearchTerm] = useState('')
    const [showModal, setShowModal] = useState(false)
    const [form, setForm] = useState<CreateStaffForm>({ ...INITIAL_FORM })
    const [createError, setCreateError] = useState('')
    const [roleFilter, setRoleFilter] = useState<'all' | 'ADMIN' | 'DEALER' | 'STAFF'>('all')

    // Temp PIN modal state
    const [showPinModal, setShowPinModal] = useState(false)
    const [tempPin, setTempPin] = useState('')
    const [tempPinStaffName, setTempPinStaffName] = useState('')
    const [deleteTarget, setDeleteTarget] = useState<Staff | null>(null)

    const queryClient = useQueryClient()
    const { hasRole, user } = useAuthStore()
    const isDealer = user?.designation === 'DEALER'

    // Always fetch ALL staff (including deleted)
    const { data: staff = [], isLoading } = useQuery({
        queryKey: ['staff'],
        queryFn: () => api.get<Staff[]>('/admin/staff?include_deleted=true'),
    })

    const filteredStaff = staff.filter((s) => {
        const matchesSearch = s.full_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            s.mobile_no.includes(searchTerm) ||
            s.designation.toLowerCase().includes(searchTerm.toLowerCase())

        const matchesRole = roleFilter === 'all' || s.designation === roleFilter

        return matchesSearch && matchesRole
    })

    const deleteMutation = useMutation({
        mutationFn: ({ id, hardDelete }: { id: number; hardDelete?: boolean }) =>
            api.delete(`/admin/staff/${id}`, { params: { hard_delete: hardDelete } }),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] }),
    })

    const restoreMutation = useMutation({
        mutationFn: (id: number) => api.post(`/admin/staff/${id}/restore`, {}),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['staff'] }),
    })

    const createMutation = useMutation({
        mutationFn: (data: CreateStaffForm) => api.post<any>('/admin/staff', data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['staff'] })
        },
    })

    const resetPinMutation = useMutation({
        mutationFn: (staffId: number) => api.post<any>('/auth/reset-pin', { staff_id: staffId }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['staff'] })
        },
    })

    const handleToggleStatus = async (s: Staff) => {
        if (s.is_deleted) {
            // Currently Deleted -> Restore
            if (confirm(`Restore ${s.full_name}?`)) {
                await restoreMutation.mutateAsync(s.staff_id)
            }
        } else {
            // Currently Active -> Delete via modal
            setDeleteTarget(s)
        }
    }

    const handleDeleteConfirm = async (hardDelete: boolean) => {
        if (deleteTarget) {
            await deleteMutation.mutateAsync({ id: deleteTarget.staff_id, hardDelete })
        }
        setDeleteTarget(null)
    }

    const handleResetPin = async (staffId: number, staffName: string) => {
        if (!confirm(`Reset PIN for ${staffName}? This will generate a temporary PIN that must be changed on next login.`)) return
        try {
            const result = await resetPinMutation.mutateAsync(staffId)
            setTempPin(result.temporary_pin)
            setTempPinStaffName(staffName)
            setShowPinModal(true)
        } catch (err: any) {
            alert(err?.response?.data?.detail || 'Failed to reset PIN')
        }
    }

    const handleCreate = async (e: React.FormEvent) => {
        e.preventDefault()
        setCreateError('')

        if (!form.full_name || !form.mobile_no || !form.email || !form.aadhaar_no) {
            setCreateError('Full Name, Mobile, Email, and Aadhaar are required.')
            return
        }

        try {
            const result = await createMutation.mutateAsync(form)
            setShowModal(false)
            setForm({ ...INITIAL_FORM })
            if (result.temp_pin) {
                setTempPin(result.temp_pin)
                setTempPinStaffName(result.full_name || form.full_name)
                setShowPinModal(true)
            }
        } catch (err: any) {
            setCreateError(err?.response?.data?.detail || err?.message || 'Failed to create staff')
        }
    }

    const openModal = () => {
        setForm({ ...INITIAL_FORM })
        if (isDealer) {
            setForm(prev => ({ ...prev, designation: 'STAFF' }))
        }
        setCreateError('')
        setShowModal(true)
    }

    const updateField = (field: keyof CreateStaffForm, value: string) => {
        setForm(prev => ({ ...prev, [field]: value }))
    }

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <div></div>
                <div className="flex gap-2">
                    {hasRole(['DEALER', 'ADMIN']) && (
                        <button className="btn btn-primary flex items-center gap-2" onClick={openModal}>
                            <Plus className="w-5 h-5" />
                            Add Staff
                        </button>
                    )}
                </div>
            </div>

            <div className="card">
                <div className="mb-4 flex gap-3">
                    <select
                        value={roleFilter}
                        onChange={(e) => setRoleFilter(e.target.value as any)}
                        className="input w-auto"
                    >
                        <option value="all">All Roles</option>
                        <option value="ADMIN">Admin</option>
                        <option value="DEALER">Dealer</option>
                        <option value="STAFF">Staff</option>
                    </select>
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                        <input
                            type="text"
                            placeholder="Search staff..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="input pl-10"
                        />
                    </div>
                </div>

                {isLoading ? (
                    <SkeletonTable rows={5} />
                ) : filteredStaff.length === 0 ? (
                    <div className="text-center py-8">
                        <p className="text-gray-500">No staff found</p>
                    </div>
                ) : (
                    <div className="table-container">
                        <table className="table">
                            <thead>
                                <tr>
                                    <th>ID</th>
                                    <th>Name</th>
                                    <th>Mobile</th>
                                    <th>Email</th>
                                    <th>Designation</th>
                                    <th>Status (Toggle)</th>
                                    <th>Joined</th>
                                    <th>Created</th>
                                    <th>Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredStaff.map((s) => (
                                    <tr key={s.staff_id} className={s.is_deleted ? 'bg-gray-50' : ''}>
                                        <td>{s.staff_id}</td>
                                        <td className="font-medium">{s.full_name}</td>
                                        <td>{s.mobile_no}</td>
                                        <td>{s.email || '-'}</td>
                                        <td>
                                            <span className="px-2 py-1 text-xs rounded-full bg-gray-100 text-gray-800">
                                                {s.designation}
                                            </span>
                                        </td>
                                        <td>
                                            <div className="flex items-center gap-2">
                                                <button
                                                    onClick={() => handleToggleStatus(s)}
                                                    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-brand-500 ${!s.is_deleted ? 'bg-green-500' : 'bg-gray-300'
                                                        }`}
                                                    title={s.is_deleted ? "Click to Activate" : "Click to Deactivate"}
                                                >
                                                    <span
                                                        className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${!s.is_deleted ? 'translate-x-6' : 'translate-x-1'
                                                            }`}
                                                    />
                                                </button>
                                                <span className={`text-xs ${s.is_deleted ? 'text-gray-500' : 'text-green-700 font-medium'}`}>
                                                    {s.is_deleted ? 'Inactive' : 'Active'}
                                                </span>
                                            </div>
                                        </td>
                                        <td>{s.joined_date ? formatDate(s.joined_date) : '-'}</td>
                                        <td>{formatDate(s.created_at)}</td>
                                        <td>
                                            <div className="flex items-center gap-2">
                                                {!s.is_deleted && (
                                                    <button
                                                        onClick={() => handleResetPin(s.staff_id, s.full_name)}
                                                        className="text-orange-600 hover:text-orange-800"
                                                        title="Reset PIN"
                                                    >
                                                        <RotateCcw className="w-4 h-4" />
                                                    </button>
                                                )}
                                                {s.is_deleted && (
                                                    <span className="text-xs text-gray-400 italic">Deleted</span>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Create Staff Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-lg shadow-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
                        <div className="flex items-center justify-between p-4 border-b">
                            <h2 className="text-xl font-semibold">Add New Staff</h2>
                            <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600">
                                <X className="w-5 h-5" />
                            </button>
                        </div>

                        <form onSubmit={handleCreate} className="p-4 space-y-4">
                            {createError && (
                                <div className="p-3 bg-red-50 border border-red-200 text-red-700 rounded-md text-sm">
                                    {createError}
                                </div>
                            )}

                            {/* Basic Info */}
                            <fieldset className="space-y-3">
                                <legend className="text-sm font-semibold text-gray-700 mb-2">Basic Information</legend>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Full Name *</label>
                                        <input type="text" className="input" value={form.full_name}
                                            onChange={e => updateField('full_name', e.target.value)} required />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Mobile No *</label>
                                        <input type="text" className="input" value={form.mobile_no}
                                            onChange={e => updateField('mobile_no', e.target.value)} required />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Email *</label>
                                        <input type="email" className="input" value={form.email}
                                            onChange={e => updateField('email', e.target.value)} required />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Designation</label>
                                        {isDealer ? (
                                            <input type="text" className="input bg-gray-100" value="STAFF" disabled />
                                        ) : (
                                            <select className="input" value={form.designation}
                                                onChange={e => updateField('designation', e.target.value)}>
                                                <option value="STAFF">STAFF</option>
                                                <option value="DEALER">DEALER</option>
                                                <option value="ADMIN">ADMIN</option>
                                            </select>
                                        )}
                                    </div>
                                </div>
                            </fieldset>

                            {/* Personal Details */}
                            <fieldset className="space-y-3">
                                <legend className="text-sm font-semibold text-gray-700 mb-2">Personal Details</legend>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Aadhaar No *</label>
                                        <input type="text" className="input" value={form.aadhaar_no}
                                            onChange={e => updateField('aadhaar_no', e.target.value)} required maxLength={12} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">PAN No</label>
                                        <input type="text" className="input" value={form.pan_no || ''}
                                            onChange={e => updateField('pan_no', e.target.value)} maxLength={10} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Joining Date</label>
                                        <input type="date" className="input" value={form.joined_date || ''}
                                            onChange={e => updateField('joined_date', e.target.value)} />
                                    </div>
                                </div>
                            </fieldset>

                            {/* Address */}
                            <fieldset className="space-y-3">
                                <legend className="text-sm font-semibold text-gray-700 mb-2">Address</legend>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <div className="sm:col-span-2">
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Address Line 1</label>
                                        <input type="text" className="input" value={form.address_line1 || ''}
                                            onChange={e => updateField('address_line1', e.target.value)} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">City</label>
                                        <input type="text" className="input" value={form.city || ''}
                                            onChange={e => updateField('city', e.target.value)} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">State</label>
                                        <input type="text" className="input" value={form.state || ''}
                                            onChange={e => updateField('state', e.target.value)} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Pincode</label>
                                        <input type="text" className="input" value={form.pincode || ''}
                                            onChange={e => updateField('pincode', e.target.value)} maxLength={6} />
                                    </div>
                                </div>
                            </fieldset>

                            {/* Bank Details */}
                            <fieldset className="space-y-3">
                                <legend className="text-sm font-semibold text-gray-700 mb-2">Bank Details</legend>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Bank Name</label>
                                        <input type="text" className="input" value={form.bank_name || ''}
                                            onChange={e => updateField('bank_name', e.target.value)} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Account No</label>
                                        <input type="text" className="input" value={form.bank_account_no || ''}
                                            onChange={e => updateField('bank_account_no', e.target.value)} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">IFSC Code</label>
                                        <input type="text" className="input" value={form.ifsc_code || ''}
                                            onChange={e => updateField('ifsc_code', e.target.value)} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">UPI ID</label>
                                        <input type="text" className="input" value={form.upi_id || ''}
                                            onChange={e => updateField('upi_id', e.target.value)} />
                                    </div>
                                </div>
                            </fieldset>

                            {/* Emergency Contact */}
                            <fieldset className="space-y-3">
                                <legend className="text-sm font-semibold text-gray-700 mb-2">Emergency Contact</legend>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Contact Name</label>
                                        <input type="text" className="input" value={form.emergency_contact_name || ''}
                                            onChange={e => updateField('emergency_contact_name', e.target.value)} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Contact No</label>
                                        <input type="text" className="input" value={form.emergency_contact_no || ''}
                                            onChange={e => updateField('emergency_contact_no', e.target.value)} />
                                    </div>
                                </div>
                            </fieldset>

                            <div className="flex justify-end gap-3 pt-4 border-t">
                                <button type="button" className="btn btn-outline" onClick={() => setShowModal(false)}>
                                    Cancel
                                </button>
                                <button type="submit" className="btn btn-primary" disabled={createMutation.isPending}>
                                    {createMutation.isPending ? 'Creating...' : 'Create Staff'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Temp PIN Modal */}
            {showPinModal && tempPin && (
                <TempPinModal
                    pin={tempPin}
                    staffName={tempPinStaffName}
                    onClose={() => {
                        setShowPinModal(false)
                        setTempPin('')
                        setTempPinStaffName('')
                    }}
                />
            )}

            <DeleteConfirmModal
                isOpen={!!deleteTarget}
                onClose={() => setDeleteTarget(null)}
                onConfirm={handleDeleteConfirm}
                itemName={deleteTarget?.full_name || ''}
                isPending={deleteMutation.isPending}
            />
        </div>
    )
}

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { setupApi } from '../api/setupApi'
import type {
    PaymentMode, ExpenseCategory, JobCardCategory,
    InsuranceCompany, Bank, DocumentType, Brand,
    ShowroomConfig
} from '../api/setupApi'
import { Link } from 'react-router-dom'
import toast from 'react-hot-toast'
import {
    Plus, Pencil, Trash2, X,
    CreditCard, FolderOpen, Wrench, Shield, Building2, FileText, Users, Tag, Store
} from 'lucide-react'
import StaffManager from '../components/StaffManager'
import { SkeletonTable } from '@/components/ui/SkeletonTable'
import DeleteConfirmModal from '@/components/ui/DeleteConfirmModal'



// ==================== GENERIC CRUD TABLE COMPONENT ====================

interface CrudField {
    key: string
    label: string
    type?: 'text' | 'select' | 'checkbox'
    required?: boolean
    options?: { value: string; label: string }[]
    placeholder?: string
}


interface CrudTableProps<T> {
    title: string
    icon: any
    queryKey: string
    fetchFn: () => Promise<T[]>
    createFn: (data: any) => Promise<T>
    updateFn: (id: number, data: any) => Promise<T>
    deleteFn: (id: number, hardDelete?: boolean) => Promise<any>
    restoreFn?: (id: number) => Promise<any>
    idField: string
    nameField: string
    fields: CrudField[]
    columns: { key: string; label: string; render?: (item: T, index: number) => React.ReactNode }[]
    enableSoftDelete?: boolean
}

function CrudTable<T extends Record<string, any>>({
    title, icon: Icon, queryKey, fetchFn, createFn, updateFn, deleteFn, restoreFn,
    idField, nameField, fields, columns, enableSoftDelete
}: CrudTableProps<T>) {
    const queryClient = useQueryClient()
    const [showForm, setShowForm] = useState(false)
    const [editingItem, setEditingItem] = useState<T | null>(null)
    const [formData, setFormData] = useState<Record<string, any>>({})
    const [deleteTarget, setDeleteTarget] = useState<T | null>(null)

    const { data: items = [], isLoading } = useQuery({
        queryKey: [queryKey],
        queryFn: fetchFn,
    })

    const createMut = useMutation({
        mutationFn: (data: any) => createFn(data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: [queryKey] })
            toast.success(`${title} created`)
            resetForm()
        },
        onError: () => toast.error(`Failed to create ${title.toLowerCase()}`),
    })

    const updateMut = useMutation({
        mutationFn: ({ id, data }: { id: number; data: any }) => updateFn(id, data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: [queryKey] })
            toast.success(`${title} updated`)
            resetForm()
        },
        onError: () => toast.error(`Failed to update ${title.toLowerCase()}`),
    })

    const deleteMut = useMutation({
        mutationFn: ({ id, hardDelete }: { id: number; hardDelete?: boolean }) => deleteFn(id, hardDelete),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: [queryKey] })
            toast.success(enableSoftDelete ? `${title} deactivated` : `${title} deleted`)
        },
        onError: () => toast.error(`Failed to delete ${title.toLowerCase()}`),
    })

    const restoreMut = useMutation({
        mutationFn: (id: number) => restoreFn!(id),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: [queryKey] })
            toast.success(`${title} restored`)
        },
        onError: () => toast.error(`Failed to restore ${title.toLowerCase()}`),
    })

    const resetForm = () => {
        setShowForm(false)
        setEditingItem(null)
        setFormData({})
    }

    const openCreate = () => {
        setEditingItem(null)
        setFormData({})
        setShowForm(true)
    }

    const openEdit = (item: T) => {
        setEditingItem(item)
        const data: Record<string, any> = {}
        fields.forEach(f => { data[f.key] = item[f.key] ?? '' })
        setFormData(data)
        setShowForm(true)
    }

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault()
        if (editingItem) {
            updateMut.mutate({ id: editingItem[idField], data: formData })
        } else {
            createMut.mutate(formData)
        }
    }

    const handleDelete = (item: T) => {
        setDeleteTarget(item)
    }

    const handleDeleteConfirm = (hardDelete: boolean) => {
        if (deleteTarget) {
            deleteMut.mutate({ id: deleteTarget[idField], hardDelete })
        }
        setDeleteTarget(null)
    }

    const handleToggleStatus = (item: T) => {
        if (!restoreFn) return
        const isDeleted = item.is_deleted || !item.is_active
        if (isDeleted) {
            if (confirm(`Restore "${item[nameField]}"?`)) {
                restoreMut.mutate(item[idField])
            }
        } else {
            setDeleteTarget(item)
        }
    }

    // Filter out status column if enableSoftDelete is on (we'll add our own)
    const displayColumns = enableSoftDelete
        ? columns.filter(c => c.key !== 'is_active' && c.key !== 'status')
        : columns

    return (
        <>
            <div>
                {/* Header */}
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                        <Icon className="w-6 h-6 text-primary-600" />
                        <h2 className="text-xl font-semibold text-gray-800">{title}s</h2>
                        <span className="text-sm text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full">
                            {items.length}
                        </span>
                    </div>
                    <button
                        onClick={openCreate}
                        className="flex items-center gap-2 px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors text-sm font-medium"
                    >
                        <Plus className="w-4 h-4" />
                        Add {title}
                    </button>
                </div>

                {/* Form Modal */}
                {showForm && (
                    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
                        <div className="bg-white rounded-xl shadow-xl w-full max-w-md">
                            <div className="flex items-center justify-between p-6 border-b">
                                <h3 className="text-lg font-semibold">
                                    {editingItem ? `Edit ${title}` : `New ${title}`}
                                </h3>
                                <button onClick={resetForm} className="p-1 hover:bg-gray-100 rounded">
                                    <X className="w-5 h-5" />
                                </button>
                            </div>
                            <form onSubmit={handleSubmit} className="p-6 space-y-4">
                                {fields.map(field => (
                                    <div key={field.key}>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">
                                            {field.label}
                                            {field.required && <span className="text-red-500 ml-1">*</span>}
                                        </label>
                                        {field.type === 'select' ? (
                                            <select
                                                value={formData[field.key] ?? ''}
                                                onChange={e => setFormData(prev => ({ ...prev, [field.key]: e.target.value }))}
                                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500"
                                            >
                                                <option value="">— Select —</option>
                                                {field.options?.map(opt => (
                                                    <option key={opt.value} value={opt.value}>{opt.label}</option>
                                                ))}
                                            </select>
                                        ) : field.type === 'checkbox' ? (
                                            <input
                                                type="checkbox"
                                                checked={!!formData[field.key]}
                                                onChange={e => setFormData(prev => ({ ...prev, [field.key]: e.target.checked }))}
                                                className="h-4 w-4 text-primary-600 border-gray-300 rounded focus:ring-primary-500"
                                            />
                                        ) : (
                                            <input
                                                type="text"
                                                value={formData[field.key] ?? ''}
                                                onChange={e => setFormData(prev => ({ ...prev, [field.key]: e.target.value }))}
                                                placeholder={field.placeholder}
                                                required={field.required}
                                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500"
                                            />
                                        )}
                                    </div>
                                ))}
                                <div className="flex gap-3 pt-2">
                                    <button
                                        type="submit"
                                        disabled={createMut.isPending || updateMut.isPending}
                                        className="flex-1 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 disabled:opacity-50 font-medium"
                                    >
                                        {createMut.isPending || updateMut.isPending ? 'Saving...' : editingItem ? 'Update' : 'Create'}
                                    </button>
                                    <button
                                        type="button"
                                        onClick={resetForm}
                                        className="flex-1 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium"
                                    >
                                        Cancel
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                )}

                {/* Table */}
                {isLoading ? (
                    <div className="bg-white rounded-xl border border-gray-200 p-6">
                        <SkeletonTable rows={5} />
                    </div>
                ) : items.length === 0 ? (
                    <div className="text-center py-12">
                        <Icon className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                        <p className="text-gray-500">No {title.toLowerCase()}s yet</p>
                        <button onClick={openCreate} className="text-primary-600 hover:underline text-sm mt-2">
                            Create your first {title.toLowerCase()}
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
                        <table className="w-full">
                            <thead>
                                <tr className="bg-gray-50 border-b border-gray-200">
                                    {displayColumns.map(col => (
                                        <th key={col.key} className="text-left px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">
                                            {col.label}
                                        </th>
                                    ))}
                                    {enableSoftDelete && (
                                        <th className="text-left px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">
                                            Status
                                        </th>
                                    )}
                                    <th className="text-right px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">
                                        Actions
                                    </th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {items.map((item, index) => {
                                    const isDeleted = item.is_deleted || !item.is_active
                                    return (
                                        <tr key={item[idField]} className={`hover:bg-gray-50 transition-colors ${isDeleted ? 'bg-gray-50' : ''}`}>
                                            {displayColumns.map(col => (
                                                <td key={col.key} className="px-4 py-3 text-sm text-gray-700">
                                                    {col.render ? col.render(item, index) : String(item[col.key] ?? '—')}
                                                </td>
                                            ))}
                                            {enableSoftDelete && (
                                                <td className="px-4 py-3 text-sm">
                                                    <div className="flex items-center gap-2">
                                                        <button
                                                            onClick={() => handleToggleStatus(item)}
                                                            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 ${!isDeleted ? 'bg-green-500' : 'bg-gray-300'
                                                                }`}
                                                        >
                                                            <span
                                                                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${!isDeleted ? 'translate-x-6' : 'translate-x-1'
                                                                    }`}
                                                            />
                                                        </button>
                                                        <span className={`text-xs ${isDeleted ? 'text-gray-500' : 'text-green-700 font-medium'}`}>
                                                            {isDeleted ? 'Inactive' : 'Active'}
                                                        </span>
                                                    </div>
                                                </td>
                                            )}
                                            <td className="px-4 py-3 text-right">
                                                <div className="flex justify-end gap-2">
                                                    {!isDeleted && (
                                                        <button
                                                            onClick={() => openEdit(item)}
                                                            className="p-1.5 text-gray-400 hover:text-primary-600 hover:bg-primary-50 rounded transition-colors"
                                                            title="Edit"
                                                        >
                                                            <Pencil className="w-4 h-4" />
                                                        </button>
                                                    )}
                                                    {!enableSoftDelete && (
                                                        <button
                                                            onClick={() => handleDelete(item)}
                                                            className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                                                            title="Delete"
                                                        >
                                                            <Trash2 className="w-4 h-4" />
                                                        </button>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    )
                                })}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            <DeleteConfirmModal
                isOpen={!!deleteTarget}
                onClose={() => setDeleteTarget(null)}
                onConfirm={handleDeleteConfirm}
                itemName={deleteTarget ? String(deleteTarget[nameField]) : ''}
                isPending={deleteMut.isPending}
            />
        </>
    )
}


