      queryClient.invalidateQueries({ queryKey: ['warranty-claims'] })
      setDeleteTarget(null)
    },
  })

  const handleDeleteConfirm = (hardDelete: boolean) => {
    if (deleteTarget) {
      deleteMutation.mutate({ id: deleteTarget.claim_id, hardDelete })
    }
  }

  const filteredClaims = claims.filter((claim) => {
    const matchesSearch =
      claim.so_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
      claim.portal_ref_no?.toLowerCase().includes(searchTerm.toLowerCase())
    const matchesStatus = !statusFilter || claim.claim_status === statusFilter
    return matchesSearch && matchesStatus
  })

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Warranty</h1>
          <p className="text-gray-600 mt-1">Manage warranty claims</p>
        </div>
        <button onClick={() => setShowForm(true)} className="btn btn-primary flex items-center gap-2">
          <Plus className="w-5 h-5" />
          New Claim
        </button>
      </div>

      <div className="flex flex-col sm:flex-row gap-4">
        <div className="flex-1">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search claims..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="input pl-10"
            />
          </div>
        </div>
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="input sm:w-48"
        >
          <option value="">All Status</option>
          <option value="RAISED">Raised</option>
          <option value="APPROVED">Approved</option>
          <option value="REJECTED">Rejected</option>
        </select>
      </div>

      <div className="card">
        {isLoading ? (
          <div className="text-center py-8">
            <p className="text-gray-500">Loading claims...</p>
          </div>
        ) : filteredClaims.length === 0 ? (
          <div className="text-center py-8">
            <p className="text-gray-500">No claims found</p>
          </div>
        ) : (
          <div className="table-container">
            <table className="table">
              <thead>
                <tr>
                  <th>Claim ID</th>
                  <th>SO Number</th>
                  <th>Portal Ref</th>
                  <th>Status</th>
                  <th>Approval Date</th>
                  <th>Created</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredClaims.map((claim) => (
                  <tr key={claim.claim_id}>
                    <td>{claim.claim_id}</td>
                    <td className="font-medium">{claim.so_number}</td>
                    <td>{claim.portal_ref_no || '-'}</td>
                    <td>
                      <span className={`px-2 py-1 text-xs rounded-full ${claim.claim_status === 'APPROVED'
                        ? 'bg-green-100 text-green-800'
                        : claim.claim_status === 'REJECTED'
                          ? 'bg-red-100 text-red-800'
                          : 'bg-yellow-100 text-yellow-800'
                        }`}>
                        {claim.claim_status}
                      </span>
                    </td>
                    <td>{claim.approval_date ? formatDate(claim.approval_date) : '-'}</td>
                    <td>{formatDate(claim.created_at)}</td>
                    <td>
                      <button
                        onClick={() => setDeleteTarget(claim)}
                        className="p-2 text-red-600 hover:bg-red-50 rounded"
                        title="Delete Claim"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showForm && (
        <ClaimForm
          onSubmit={(data) => createMutation.mutate(data)}
          onClose={() => setShowForm(false)}
          isLoading={createMutation.isPending}
        />
      )}

      <DeleteConfirmModal
        isOpen={!!deleteTarget}
        onClose={() => setDeleteTarget(null)}
        onConfirm={handleDeleteConfirm}
        itemName={deleteTarget ? `Claim SO: ${deleteTarget.so_number}` : ''}
        isPending={deleteMutation.isPending}
      />
    </div>
  )
}

import { create } from 'zustand'
import { persist, createJSONStorage } from 'zustand/middleware'
import { useEffect, useState } from 'react'

export type UserRole = 'ADMIN' | 'DEALER' | 'STAFF'

export interface User {
  staff_id: number
  name?: string
  designation: string
  role: UserRole
  force_pin_change: boolean
}

interface AuthState {
  token: string | null
  user: User | null
  isAuthenticated: boolean
  login: (token: string) => void
  logout: () => void
  hasRole: (roles: UserRole[]) => boolean
  setAuth: (user: User, token: string) => void
  clearAuth: () => void
}

// Helper function to decode JWT token
function decodeJWT(token: string): any {
  try {
    const base64Url = token.split('.')[1]
    const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/')
    const jsonPayload = decodeURIComponent(
      atob(base64)
        .split('')
        .map((c) => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
        .join('')
    )
    return JSON.parse(jsonPayload)
  } catch (error) {
    console.error('Error decoding JWT:', error)
    return null
  }
}

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      token: null,
      user: null,
      isAuthenticated: false,

      login: (token: string) => {
        const decoded = decodeJWT(token)
        console.log('Decoded Token:', decoded) // Debugging
        if (decoded) {
          const rawRole = decoded.role || decoded.designation || 'STAFF'
          const user: User = {
            staff_id: decoded.staff_id || decoded.sub || 0,
            name: decoded.name || decoded.designation || '',
            designation: decoded.designation || '',
            role: rawRole.toUpperCase() as UserRole,
            force_pin_change: decoded.force_pin_change || false,
          }
          console.log('User Role Set To:', user.role) // Debugging
          set({ token, user, isAuthenticated: true })
        } else {
          set({ token: null, user: null, isAuthenticated: false })
        }
      },

      logout: () => {
        set({ token: null, user: null, isAuthenticated: false })
      },

      hasRole: (roles: UserRole[] | UserRole) => {
        const { user } = get()
        if (!user || !user.role) return false

        // Admin bypasses all checks in frontend
        if (user.role.toUpperCase() === 'ADMIN' || user.designation?.toUpperCase() === 'ADMIN') {
          return true;
        }

        // Add array-type safety to prevent .includes crash
        const rolesArray = Array.isArray(roles) ? roles : [roles]

        // Check exact match OR uppercase match (for legacy state)
        return rolesArray.includes(user.role as UserRole) || rolesArray.includes(user.role.toUpperCase() as UserRole)
      },

      setAuth: (user: User, token: string) => {
        set({ token, user, isAuthenticated: true })
      },

      clearAuth: () => {
        set({ token: null, user: null, isAuthenticated: false })
      },
    }),
    {
      name: 'auth-storage',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        token: state.token,
        user: state.user,
        isAuthenticated: state.isAuthenticated
      }),
    }
  )
)

// Custom hook to wait for hydration
export const useAuthHydration = () => {
  const [hydrated, setHydrated] = useState(false)

  useEffect(() => {
    // Check if already hydrated via persist API
    const unsubFinishHydration = useAuthStore.persist.onFinishHydration(() => {
      setHydrated(true)
    })

    // If already hydrated (happens on fast loads)
    if (useAuthStore.persist.hasHydrated()) {
      setHydrated(true)
    }

    return () => {
      unsubFinishHydration()
    }
  }, [])

  return hydrated
}

import { create } from 'zustand'
import { leadsApi, Lead } from '@/modules/crm/api/leads'

interface CrmState {
    leads: Lead[]
    enquiries: any[] // TODO: Define Enquiry Interface
    lastFetched: number | null
    isLoading: boolean
    error: string | null

    // Actions
    fetchLeads: (force?: boolean) => Promise<void>
    fetchEnquiries: (force?: boolean) => Promise<void>
    addLead: (lead: Lead) => void
    updateLead: (lead_id: number, data: Partial<Lead>) => void
    removeLead: (lead_id: number) => void
}

export const useCrmStore = create<CrmState>((set, get) => ({
    leads: [],
    enquiries: [],
    lastFetched: null,
    isLoading: false,
    error: null,

    fetchLeads: async (force = false) => {
        const state = get()
        // Cache validity: 5 minutes
        const isCacheValid = state.lastFetched && (Date.now() - state.lastFetched < 5 * 60 * 1000)

        if (!force && isCacheValid && state.leads.length > 0) {
            return
        }

        set({ isLoading: true, error: null })
        try {
            const data = await leadsApi.list()
            set({
                leads: data,
                lastFetched: Date.now(),
                isLoading: false
            })
        } catch (err: any) {
            set({ error: err.message, isLoading: false })
        }
    },

    fetchEnquiries: async (force = false) => {
        set({ isLoading: true, error: null })
        try {
            // Lazy load dependencies or just import them
            const { crmApi } = await import('@/modules/crm/api/crmApi')
            const data = await crmApi.getLeads() // Placeholder: need getEnquiries endpoint in crmApi
            // Actually crmApi doesn't have listEnquiries visible in Step 369.
            // But routes created getEnquiries? No. 
            // Step 20ish showed "list_enquiries".
            // I will assume endpoint is /crm/enquiries
            set({ enquiries: [], isLoading: false }) // Stubbed for now until endpoints verified
        } catch (err: any) {
            set({ error: err.message, isLoading: false })
        }
    },

    addLead: (lead) => set((state) => ({
        leads: [lead, ...state.leads]
    })),

    updateLead: (lead_id, data) => set((state) => ({
        leads: state.leads.map((l) => l.lead_id === lead_id ? { ...l, ...data } : l)
    })),

    removeLead: (lead_id) => set((state) => ({
        leads: state.leads.filter((l) => l.lead_id !== lead_id)
    }))
}))

import { create } from 'zustand'
import { api } from '@/lib/api'

interface MasterState {
    leadStatuses: any[]
    enquiryStatuses: any[]
    brands: any[]
    vehicleModels: any[]

    // Flags
    isInitialized: boolean
    isLoading: boolean
    error: string | null

    // Actions
    fetchMasterData: () => Promise<void>
    getLeadStatusName: (id: number) => string
    getEnquiryStatusName: (id: number) => string
    getBrandName: (id: number) => string
    getVehicleModelName: (id: number) => string
}

export const useMasterStore = create<MasterState>((set, get) => ({
    leadStatuses: [],
    enquiryStatuses: [],
    brands: [],
    vehicleModels: [],
    isInitialized: false,
    isLoading: false,
    error: null,

    fetchMasterData: async () => {
        // Debounce if already initialized or loading
        if (get().isInitialized || get().isLoading) return

        set({ isLoading: true, error: null })
        try {
            // Parallel fetch for best performance
            const [lStatus, eStatus, brands, models] = await Promise.all<any[]>([
                api.get('/crm/master/lead-statuses').catch(() => []),
                api.get('/crm/master/enquiry-statuses').catch(() => []),
                // We might need an endpoint for brands/models if they are not under /crm/master
                // Assuming endpoints exist, or we default to empty if not yet implemented
                Promise.resolve([]),
                Promise.resolve([])
            ])

            set({
                leadStatuses: lStatus,
                enquiryStatuses: eStatus,
                brands: brands as any[],
                vehicleModels: models as any[],
                isInitialized: true,
                isLoading: false
            })
        } catch (err: any) {
            set({ error: err.message || 'Failed to load master data', isLoading: false })
        }
    },

    getLeadStatusName: (id: number) => {
        const item = get().leadStatuses.find((s: any) => s.status_id === id)
        return item ? item.status_name : `ID: ${id}`
    },

    getEnquiryStatusName: (id: number) => {
        const item = get().enquiryStatuses.find((s: any) => s.status_id === id)
        return item ? item.status_name : `ID: ${id}`
    },

    getBrandName: (id: number) => {
        const item = get().brands.find((s: any) => s.brand_id === id)
        return item ? item.brand_name : `ID: ${id}`
    },

    getVehicleModelName: (id: number) => {
        const item = get().vehicleModels.find((s: any) => s.vehicle_model_id === id)
        return item ? item.model_name : `ID: ${id}`
    }
}))
